	INIT_MSG_WITH_BUFFER(MSG_FC_CITYWAR_BRING_SUMOFTEX_OK, T_FC_CITYWAR_BRING_SUMOFTEX_OK, pS2CBringOK, SendBuf);
	pS2CBringOK->nBroughtSumOfTex	= nBringTex;
