///////////////////////////////////////////////////////////////////////////////
/// \fn			ProcessResult CFieldIOCPSocket::Process_FN_MONSTER_HPTALK(const char* pPacket, int nLength, int &nBytesUsed)	
/// \brief		ŔÎÇÇ´ĎĆĽ - ¸ó˝şĹÍ ´ë»ç Ĺ¬¶óŔĚľđĆ®·Î ŔüĽŰ
/// \author		dhjin
/// \date		2009-09-09 ~ 2010
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
ProcessResult CFieldIOCPSocket::Process_FN_MONSTER_HPTALK(const char* pPacket, int nLength, int &nBytesUsed) {

	//10-08-2015 by inetpub - filtering BIN<=>BIN allowed ip
	if (FALSE == g_pFieldGlobal->CheckAllowedToolIP(this->GetPeerIP()))
	{
		char szTempLog[1024];
		sprintf(szTempLog, "[PacketFilter] Hack by sending BIN<=>BIN packet detected! Hacker was trying to use :: Process_FN_MONSTER_HPTALK, Hacker IP :: [%s]\r\n", this->GetPeerIP());
		g_pFieldGlobal->WriteSystemLog(szTempLog);
		return RES_RETURN_FALSE;
	}
	//end of 10-08-2015 by inetpub

	DECLARE_MESSAGE_AND_CHECK_SIZE(pPacket, nLength, nBytesUsed, T_FN_MONSTER_HPTALK, MSG_FN_MONSTER_HPTALK, pRMsg);
	
	INIT_MSG_WITH_BUFFER(MSG_FC_MONSTER_HPTALK, T_FC_MONSTER_HPTALK, pSMsg, pSBuf);
	pSMsg->MonsterIndex		= pRMsg->MonsterIndex;
	pSMsg->MonsterUnitKind	= pRMsg->MonsterUnitKind;
	pSMsg->HPTalkImportance = pRMsg->HPTalkImportance;
	pSMsg->HPCameraTremble	= pRMsg->HPCameraTremble;
	pSMsg->TargetIndex		= pRMsg->TargetIndex;
	STRNCPY_MEMSET(pSMsg->HPTalk, pRMsg->HPTalk, SIZE_MAX_HPTALK_DESCRIPTION);

	switch (pRMsg->HPTalkImportance) {
		case HPACTION_TALK_IMPORTANCE_CHANNEL : { 
			CFieldMapChannel *pFMChann = ms_pFieldIOCP->GetFieldMapChannelByMapChannelIndex(pRMsg->ChannelIndex); 
			if(NULL == pFMChann) {
				return RES_BREAK;
			}
			pFMChann->SendMessageToAllInChannel(pSBuf, MSG_SIZE(MSG_FC_MONSTER_HPTALK));
		} break;
		case HPACTION_TALK_IMPORTANCE_INFL : {
			// ľî¶˛ ąć˝ÄŔ¸·Î ĽĽ·ÂŔ» ±¸şĐÇŇ°ÍŔÎÁö ¸đ¸Ą´Ů. ľĆÁ÷ ąĚ±¸Çö 
		 } break;
		case HPACTION_TALK_IMPORTANCE_ALL : {
			ms_pFieldIOCP->SendMessageToAllClients(pSBuf, MSG_SIZE(MSG_FC_MONSTER_HPTALK), INFLUENCE_TYPE_ALL_MASK);
		} break;
	}

	CAtumLogSender::SendLogMessageHPActionTalk(pRMsg->MonsterUnitKind, pRMsg->HPTalk);	// 2009-09-09 ~ 2010 by dhjin, ŔÎÇÇ´ĎĆĽ - ŔÎÇÇ °ÔŔÓ·Î±× Ăß°ˇ, ¸ó˝şĹÍ ´ëČ­ »çżë˝Ă
	
	return RES_RETURN_TRUE;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			ProcessResult CFieldIOCPSocket::Process_FN_BATTLE_ATTACK_SKILL_CANCEL(const char* pPacket, int nLength, int &nBytesUsed) 
/// \brief		ŔÎÇÇ´ĎĆĽ(±âÁöąćľî) - 
/// \author		dhjin
/// \date		2010-03-31
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
ProcessResult CFieldIOCPSocket::Process_FN_BATTLE_ATTACK_SKILL_CANCEL(const char* pPacket, int nLength, int &nBytesUsed) 
{
	//10-08-2015 by inetpub - filtering BIN<=>BIN allowed ip
	if (FALSE == g_pFieldGlobal->CheckAllowedToolIP(this->GetPeerIP()))
	{
		char szTempLog[1024];
		sprintf(szTempLog, "[PacketFilter] Hack by sending BIN<=>BIN packet detected! Hacker was trying to use :: Process_FN_BATTLE_ATTACK_SKILL_CANCEL, Hacker IP :: [%s]\r\n", this->GetPeerIP());
		g_pFieldGlobal->WriteSystemLog(szTempLog);
		return RES_RETURN_FALSE;
	}
	//end of 10-08-2015 by inetpub

	DECLARE_MESSAGE_AND_CHECK_SIZE(pPacket, nLength, nBytesUsed, T_FN_BATTLE_ATTACK_SKILL_CANCEL, MSG_FN_BATTLE_ATTACK_SKILL_CANCEL, pRMsg);
	
	//g_pFieldGlobal->WriteSystemLogEX(TRUE, "[TEMP] CFieldIOCPSocket::Process_FN_BATTLE_ATTACK_SKILL_CANCEL Map(%s) MonIdx(%d) SkillItemNum(%d) \r\n", GetMapString(pRMsg->MapInfo, string()), pRMsg->MonsterIndex, pRMsg->SkillItemNum);
	
	CFieldMonster *ptmFMonster = m_pFieldMapProjectForNPC->GetFieldMonsterW(pRMsg->MapInfo.ChannelIndex, pRMsg->MonsterIndex, 100);
	if(NULL == ptmFMonster
		|| ptmFMonster->m_enMonsterState != MS_PLAYING
		|| TRUE == COMPARE_BODYCON_BIT(ptmFMonster->BodyCondition, BODYCON_DEAD_MASK)) {
		return RES_BREAK;
	}

	INIT_MSG_WITH_BUFFER(MSG_FC_MONSTER_SKILL_CANCEL, T_FC_MONSTER_SKILL_CANCEL, msgUseSkillOK, SendBuf);
	msgUseSkillOK->SkillItemNum	= pRMsg->SkillItemNum;
	msgUseSkillOK->MonsterIndex	= pRMsg->MonsterIndex;
	ptmFMonster->m_pCurrentFieldMapChannelMonster->SendMessageToAllInChannel(SendBuf, MSG_SIZE(MSG_FC_MONSTER_SKILL_CANCEL));

	return RES_RETURN_TRUE;
}
enum
{
	PLAYTIME = 0,
	FAME,
	LVL,
	WP,
	_ARENA,
	PVP,
	MULTI_RANK_CNT
};
void CFieldIOCPSocket::RunRanksBuff(bool bOnlyNationBuff/* = false*/)
{
	/*FFA buffs*/
	if (this->m_character.MapChannelIndex.MapIndex == 9003)
	{//nation buff bool because its in minuteky work 17851010 17851020 17851030
		if (!this->m_SkillManager.IsSkillActivatedByItemNum(17851010))
			this->ApplyBuffSkill(17851010);

		if (!this->m_SkillManager.IsSkillActivatedByItemNum(17851020))
			this->ApplyBuffSkill(17851020);

		if (!this->m_SkillManager.IsSkillActivatedByItemNum(17851030))
			this->ApplyBuffSkill(17851030);

		return; //dont process other buffs
	}
	
	if (this->m_SkillManager.IsSkillActivatedByItemNum(17851010))
		this->ReleaseBuffSkill(17851010);
	if (this->m_SkillManager.IsSkillActivatedByItemNum(17851020))
		this->ReleaseBuffSkill(17851020);
	if (this->m_SkillManager.IsSkillActivatedByItemNum(17851030))
		this->ReleaseBuffSkill(17851030);
	
	/*
	LOOSING NATIONS BANANA BUFF
*/
#ifndef _INET_DISABLE_LOOSERS_BUFF //buff loosing nation
	int arNationSkillNum[] = {
			17841500, //lv1
			17841501, //lv2
			17841502, //lv3
			17841503, //lv4
			17841504, //lv5
			17841505,
			17841506,
			17841507,
			17841508,
			17841509, //lv10
	};
	int nAniWins = ms_pFieldIOCP->m_nPlayersPointsANI - ms_pFieldIOCP->m_nPlayersPointsBCU;
	int nBcuWins = ms_pFieldIOCP->m_nPlayersPointsBCU - ms_pFieldIOCP->m_nPlayersPointsANI;
	int nRunBuffNum = 0;

	if (nAniWins > 0) //ani wins
	{
		if (nAniWins >= 50 && nAniWins < 60)
			nRunBuffNum = arNationSkillNum[0];

		if (nAniWins >= 60 && nAniWins < 70)
			nRunBuffNum = arNationSkillNum[1];

		if (nAniWins >= 70 && nAniWins < 80)
			nRunBuffNum = arNationSkillNum[2];

		if (nAniWins >= 80 && nAniWins < 90)
			nRunBuffNum = arNationSkillNum[3];

		if (nAniWins >= 90 && nAniWins < 100)
			nRunBuffNum = arNationSkillNum[4];

		if (nAniWins >= 100 && nAniWins < 110)
			nRunBuffNum = arNationSkillNum[5];

		if (nAniWins >= 110 && nAniWins < 120)
			nRunBuffNum = arNationSkillNum[6];

		if (nAniWins >= 120 && nAniWins < 130)
			nRunBuffNum = arNationSkillNum[7];

		if (nAniWins >= 130 && nAniWins < 140)
			nRunBuffNum = arNationSkillNum[8];

		if (nAniWins >= 140)
			nRunBuffNum = arNationSkillNum[9];
	}

	if (nBcuWins > 0)
	{
		if (nBcuWins >= 50 && nBcuWins < 60)
			nRunBuffNum = arNationSkillNum[0];

		if (nBcuWins >= 60 && nBcuWins < 70)
			nRunBuffNum = arNationSkillNum[1];

		if (nBcuWins >= 70 && nBcuWins < 80)
			nRunBuffNum = arNationSkillNum[2];

		if (nBcuWins >= 80 && nBcuWins < 90)
			nRunBuffNum = arNationSkillNum[3];

		if (nBcuWins >= 90 && nBcuWins < 100)
			nRunBuffNum = arNationSkillNum[4];

		if (nBcuWins >= 100 && nBcuWins < 110)
			nRunBuffNum = arNationSkillNum[5];

		if (nBcuWins >= 110 && nBcuWins < 120)
			nRunBuffNum = arNationSkillNum[6];

		if (nBcuWins >= 120 && nBcuWins < 130)
			nRunBuffNum = arNationSkillNum[7];

		if (nBcuWins >= 130 && nBcuWins < 140)
			nRunBuffNum = arNationSkillNum[8];

		if (nBcuWins >= 140)
			nRunBuffNum = arNationSkillNum[9];
	}

	if(this->m_SkillManager.IsSkillActivatedByItemNum(nRunBuffNum)) // the same buff already activated so dont do reactivate
		return;

	for (int i = 0; i < 10; i++) {
		if (this->m_SkillManager.IsSkillActivatedByItemNum(arNationSkillNum[i])) {
			if (this->ReleaseBuffSkill(arNationSkillNum[i])) {
				SendString128(STRING_128_ADMIN_CMD, "\\nLosing nation buff cancelled! Points ANI[%d] BCU[%d]\\n", ms_pFieldIOCP->m_nPlayersPointsANI, ms_pFieldIOCP->m_nPlayersPointsBCU);
			}
		}
	}
	
	if ((this->ms_pFieldIOCP->m_InflWarManager.CheckSummonBossAndStrategyPoint() || this->ms_pFieldIOCP->m_OutPostManager.CheckALLOutPostWaring()) && !g_pFieldGlobal->IsArenaServer()) {
		if (FALSE == IS_INFINITY_STATE_PLAYING(this->m_InfinityPlayingInfo.InfinityState) && ARENA_STATE_NONE == this->m_ArenaInfo.State) {
			if (COMPARE_INFLUENCE(m_character.InfluenceType, INFLUENCE_TYPE_ANI) && nBcuWins > 0 && nRunBuffNum > 0) {
				this->ApplyBuffSkill(nRunBuffNum);
				SendString128(STRING_128_ADMIN_CMD, "\\a[\\eBCU\\a] have more active players now! Active Player Points (Level/10) difference: %d\\a", nBcuWins);
				SendString128(STRING_128_ADMIN_CMD, "\\tLosing nation buff applied!\\t");
				SendString128(STRING_128_ADMIN_CMD, "\\l Points \\cANI[%d]\\e BCU[%d]\\e \\lDiff: %d" , ms_pFieldIOCP->m_nPlayersPointsANI, ms_pFieldIOCP->m_nPlayersPointsBCU, nBcuWins);
				SendString128(STRING_128_ADMIN_CMD, "\\l Players count \\gCounted[%d]\\a Total[%d]\\l -\\c ANI Counted[%d]\\e BCU Counted[%d]\\e" , ms_pFieldIOCP->m_nPlayersChecked, ms_pFieldIOCP->m_nPlayersTotal, ms_pFieldIOCP->m_nPlayersCheckedA, ms_pFieldIOCP->m_nPlayersCheckedB);
			}
			else if (COMPARE_INFLUENCE(m_character.InfluenceType, INFLUENCE_TYPE_VCN) && nAniWins > 0 && nRunBuffNum > 0) {
				this->ApplyBuffSkill(nRunBuffNum);
				SendString128(STRING_128_ADMIN_CMD, "\\a[\\cANI\\a] have more active players now! Active Player Points (Level/10) difference: %d\\a", nAniWins);
				SendString128(STRING_128_ADMIN_CMD, "\\tLosing nation buff applied!\\t");
				SendString128(STRING_128_ADMIN_CMD, "\\l Points \\cANI[%d]\\e BCU[%d]\\e \\lDiff: %d", ms_pFieldIOCP->m_nPlayersPointsANI, ms_pFieldIOCP->m_nPlayersPointsBCU, nAniWins);
				SendString128(STRING_128_ADMIN_CMD, "\\l Players count \\gCounted[%d]\\a Total[%d]\\l -\\c ANI Counted[%d]\\e BCU Counted[%d]\\e", ms_pFieldIOCP->m_nPlayersChecked, ms_pFieldIOCP->m_nPlayersTotal, ms_pFieldIOCP->m_nPlayersCheckedA, ms_pFieldIOCP->m_nPlayersCheckedB);
			}
		}
	}
	if(bOnlyNationBuff)
		return;

#endif
	if (!g_pFieldGlobal->IsArenaServer()) {
		/*
			OUTPOST BUFFS (brigade)
		*/
		if (ms_pFieldIOCP->m_OutPostManager.GetOutPostCityMapIndexByGuildUID(this->m_character.GuildUniqueNumber) > 0)
		{ //player is in guild that have outpost atm
			this->ApplyBuffSkill(17841303);
		}
		/*leaders brigade buff*/
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_VCN && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetVCNLeaderGuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841304);
		}
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_ANI && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetANILeaderGuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841304);
		}
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_VCN && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetVCNSubLeader1GuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841305);
		}
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_VCN && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetVCNSubLeader2GuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841306);
		}
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_ANI && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetANISubLeader1GuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841305);
		}
		if (this->m_character.InfluenceType == INFLUENCE_TYPE_ANI && this->m_character.GuildUniqueNumber == ms_pFieldIOCP->m_InflWarManager.GetANISubLeader2GuildUID() && this->m_character.GuildUniqueNumber != 0) {
			this->ApplyBuffSkill(17841306);
		}
		/*
			LEADERS BUFF
		*/
		if (COMPARE_RACE(this->m_character.Race, RACE_INFLUENCE_LEADER))
		{
			this->ApplyBuffSkill(17841300);
		}
		else if (COMPARE_RACE(this->m_character.Race, RACE_INFLUENCE_SUBLEADER_1))
		{
			this->ApplyBuffSkill(17841301);
		}
		else if (COMPARE_RACE(this->m_character.Race, RACE_INFLUENCE_SUBLEADER_2))
		{
			this->ApplyBuffSkill(17841302);
		}
	}
	/*
		RANKS BUFF
	*/
#ifdef _INET_RANKBUFF
	int arRankSkillNum[] = {
		17841051, 17841052, 17841053,
		17841054, 17841055, 17841056,
		17841057, 17841058, 17841059,
		17841060, 17841061, 17841062,
		17841063, 17841064, 17841065,
		17841066, 17841067, 17841068,
		17841069, 17841070, 17841071
	};
//13/02/25 Inet - donator ranks
	int arDRankSkillNum[] = {
		0, 17841072, 17841073, 17841074, 17841075,
		17841076 //- admin rank
		//new ranks 
		, 17841077,17841078,17841079,17841080,
		//right sided ranks
		17841081,17841082,17841083,17841084//10,11,12,13
		,17841085,17841086,17841087,17841088//14,15,16,17
		,17841089,17841090 //18,19	
//new ranks in format
//		,ItemNum //rank 20
//		,ItemNum //rank 21
	};
	//13/02/25 Inet - donator ranks definitions
	short adminRankItem = 17841071; //num of rank only for admin - automatically set for GM and admin
	short rankNumberOverArrayNum = 17841090; //if rank is set too big and no skill item can be automatically set for it then set this rank (example we have 5 ranks and you set rank num 6 or bigger for player)

	int maxDonatorRankLevel = (int)sizeof(arDRankSkillNum) - 1; //last rank number - cant be bigger than count of array! (no need to change this)

	float fMultiplier[6];
	//level
	int nLevOfEnemy = m_character.Level;

	if (nLevOfEnemy > CHARACTER_MAX_LEVEL)
		nLevOfEnemy = CHARACTER_MAX_LEVEL;

	fMultiplier[LVL] = (static_cast<float>(nLevOfEnemy) / static_cast<float>(CHARACTER_MAX_LEVEL)) * 100.0f;
	//fame	
	const auto nFame = m_character.Propensity + 1; //for 0 division

	int nFameReq;

	if (IS_BT(m_character.UnitKind)) //bg
		nFameReq = 18000;
	else if (IS_OT(m_character.UnitKind)) //mg
		nFameReq = 8000;
	else if (IS_DT(m_character.UnitKind)) //ag
		nFameReq = 20000;
	else  //ig
		nFameReq = 15000;

	fMultiplier[FAME] = (static_cast<float>(nFame) / static_cast<float>(nFameReq)) * 100.0f;
	//playtime
	fMultiplier[PLAYTIME] = ((static_cast<float>(m_character.TotalPlayTime) / (24.0f * 3600.0f)) / 31.0f) * 100.0f;
	//CWP
	fMultiplier[WP] = (static_cast<float>(m_character.CumulativeWarPoint + 1) / 10000001.0f) * 100.0f;
	//ARENA
	fMultiplier[_ARENA] = (static_cast<float>(m_character.ArenaWin + 1) / 51.0f) * 100.0f;
	//PVP
	fMultiplier[PVP] = (static_cast<float>(m_character.PKWinPoint + 1) / 101.0f) * 100.0f;


	for (auto& g : fMultiplier) {
		if (g > 100.0f)
			g = 100.0f;
		else if (g <= 0.0f)
			g = 0.0f;
	}

	auto fFinalMultiplier = 0.0f;

	for (auto& m : fMultiplier)
		fFinalMultiplier += m;


	INET_RANKING nPointTable[] =
	{
			{	0	,	1600	,	STRMSG_C_RANK_0000	,	0	},
{	1600	,	5400	,	STRMSG_C_RANK_0001	,	1	},
{	5400	,	9200	,	STRMSG_C_RANK_0002	,	2	},
{	9200	,	13000	,	STRMSG_C_RANK_0003	,	3	},
{	13000	,	16800	,	STRMSG_C_RANK_0004	,	4	},
{	16800	,	20600	,	STRMSG_C_RANK_0005	,	5	},
{	20600	,	24400	,	STRMSG_C_RANK_0006	,	6	},
{	24400	,	28200	,	STRMSG_C_RANK_0007	,	7	},
{	28200	,	32000	,	STRMSG_C_RANK_0008	,	8	},
{	32000	,	35800	,	STRMSG_C_RANK_0009	,	9	},
{	35800	,	39600	,	STRMSG_C_RANK_0010	,	10	},
{	39600	,	43400	,	STRMSG_C_RANK_0011	,	11	},
{	43400	,	47200	,	STRMSG_C_RANK_0012	,	12	},
{	47200	,	51000	,	STRMSG_C_RANK_0013	,	13	},
{	51000	,	54800	,	STRMSG_C_RANK_0014	,	14	},
{	54800	,	58600	,	STRMSG_C_RANK_0015	,	15	},
{	58600	,	62400	,	STRMSG_C_RANK_0016	,	16	},
{	62400	,	66200	,	STRMSG_C_RANK_0017	,	17	},
{	66200	,	70000	,	STRMSG_C_RANK_0018	,	18	},
{	70000	,	73800	,	STRMSG_C_RANK_0019	,	19	}
	};

	const int nRace = m_character.Race;
	const auto fMultiplier2 = fFinalMultiplier;

	if (nRace > 128 && nRace <= 258)
	{
		this->ApplyBuffSkill(adminRankItem);
	}
	else
	{

		int nPointForSearch = fMultiplier2 * nLevOfEnemy;
		if (nPointForSearch >= 73800)
			nPointForSearch = 73800;
		for (auto i = 0; i < 20; i++)
		{

			if (IS_IN_RANGE(nPointTable[i].PointsMin, nPointForSearch, nPointTable[i].PointsMax))
				this->ApplyBuffSkill(arRankSkillNum[i]); //apply normal rank buff
		}
	}
	//19-09-2023 by Inet - rgb support
	CAtumSJ::DRankColorRet color = CAtumSJ::GetDRankColor(m_character.PCBangTotalPlayTime);

	if (color.nRankNum <= maxDonatorRankLevel) //check for max id
		this->ApplyBuffSkill(arDRankSkillNum[color.nRankNum]); //apply donator rank buff
	else if (color.nRankNum > maxDonatorRankLevel && color.nRankNum < 1000) //max 999 possible dont change this!
		this->ApplyBuffSkill(rankNumberOverArrayNum); //if idx too big applly max rank

	SendString128(STRING_128_USER_NOTICE, "\\gRank buffs applied!\\g");
#endif
}
