///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItem_ENG_2(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_nTotalPrice/*=0*/)
/// \brief		// 2008-03-17 by cmkwon, Gameforge4D_Eng şô¸µ ¸đµâ ż¬µżÇĎ±â - 
/// \author		cmkwon
/// \date		2008-03-17 ~ 2008-03-17
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItem_ENG_2(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_nTotalPrice/*=0*/)
{
#if defined(_DEBUG)
	///////////////////////////////////////////////////////////////////////////////
	// 2009-03-02 by cmkwon, ł»şÎ Ĺ×Ľ·żˇĽ­ Äł˝¬ Ć÷ŔÎĆ® °ü·Ă ĽöÁ¤(µđąö±× ¸đµĺ˝Ă¸¸ µżŔŰ) - Gameforge4D Ăł¸®
	if(g_pFieldGlobal->InMasangServer())
	{
		*o_pMCash		= 50000;																// CashPoint
		*o_pGiftCard	= (NULL == i_pItem) ? *o_pMCash : *o_pMCash - i_pItem->CashPrice;		// BonusPoint
		*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;												// Total Cash
		return ERR_NO_ERROR;
	}
#endif

	if(NULL == ms_pGFBillingRequest)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_ENG_2_ library error !!, hBillingLibrary(0x%X) ms_pGFBillingRequest(0x%X)\r\n"
			, ms_hBillingLibrary, ms_pGFBillingRequest);
		return ERR_CASH_mgQueryMall_ERROR;
	}
	GFSBILLING_REQ_DATA	tmBReq;		MEMSET_ZERO(&tmBReq, sizeof(tmBReq));
	GFSBILLING_RET_DATA	tmBRet;		MEMSET_ZERO(&tmBRet, sizeof(tmBRet));

	tmBReq.nCommand			= GFBILLING_CMD_REQUEST;	// 2008-03-17 by cmkwon, GFBILLING_CMD_REQUEST		302		//just ask how much money/milage user has, dont buy anything (normally returns GFERR_DB_SUCCESS)
	tmBReq.nGameUID			= m_character.AccountUniqueNumber;		// 2008-03-17 by cmkwon, ŔÇąĚ ľřÁö¸¸ Gameforge4D żˇĽ­ AccountUID ¸¦ łÖľî ÁÖ±â¸¦ żäĂ»ÇÔ
	STRNCPY_MEMSET(tmBReq.szAccountName, m_character.AccountName, min(SIZE_MAX_ACCOUNT_NAME, GFMSBILLING_SIZE_MAX_ACCOUNT_NAME));
	STRNCPY_MEMSET(tmBReq.szCharacterName, m_character.CharacterName, min(SIZE_MAX_CHARACTER_NAME, GFMSBILLING_SIZE_MAX_CHARACTER_NAME));
	STRNCPY_MEMSET(tmBReq.szUserIP, GetPeerIP(), SIZE_MAX_IPADDRESS);
	if(i_pItem)
	{// if buy item
		
		tmBReq.nCommand				= GFBILLING_CMD_EXECUTE;		// 2008-03-17 by cmkwon, GFBILLING_CMD_EXECUTE		301		//buy given item for given user
		sprintf(tmBReq.szItemNum, "%d", i_pItem->ItemNum);
		STRNCPY_MEMSET(tmBReq.szItemName, i_pItem->ItemName, SIZE_MAX_ITEM_NAME);
		tmBReq.nBuyItemCount		= 1;					// ±¸¸Ĺ Ä«żîĆ®
		tmBReq.nItemUnitPrice		= i_pItem->CashPrice;	// 1°ł´ç °ˇ°Ý
	}

// 2009-03-02 by cmkwon, ł»şÎ Ĺ×Ľ·żˇĽ­ Äł˝¬ Ć÷ŔÎĆ® °ü·Ă ĽöÁ¤(µđąö±× ¸đµĺ˝Ă¸¸ µżŔŰ) - Ŕ§żˇĽ­ Ăł¸®ÇĎ°Ô ĽöÁ¤
// #if defined(_DEBUG)		// 2008-04-03 by cmkwon, µđąö±× ¸đµĺżˇĽ­¸¸ Ăł¸®
// 	///////////////////////////////////////////////////////////////////////////////
// 	// 2008-04-03 by cmkwon, ¸¶»ó ł»şÎ Ľ­ąöżˇĽ­ Ĺ×˝şĆ®¸¦ Ŕ§ÇŘ
// 	if(g_pFieldGlobal->InMasangServer())
// 	{
// 		tmBRet.nCashPoint	= 50000;
// 		tmBRet.nBonusPoint	= (NULL == i_pItem) ? 50000 : 50000 - i_pItem->CashPrice;
// 
// 		*o_pMCash		= tmBRet.nCashPoint;			// CashPoint
// 		*o_pGiftCard	= tmBRet.nBonusPoint;			// BonusPoint
// 		*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;		// Total Cash
// 		return ERR_NO_ERROR;
// 	}
// #endif

	// 2009-05-25 by cmkwon, Gameforge4D ˝Ă˝şĹŰ ·Î±× Ăß°ˇ(şô¸µ °ü·Ă) - ČŁĂâŔü
	g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::CashItem_ENG_2 before call ms_pGFBillingRequest# %s Command(%d) \r\n", GetCharacterString(&m_character, string()), tmBReq.nCommand);

	ms_pGFBillingRequest(MSBILLING_DB_SERVER_IP, MSBILLING_DB_SERVER_PORT, &tmBReq, &tmBRet);

	// 2009-05-25 by cmkwon, Gameforge4D ˝Ă˝şĹŰ ·Î±× Ăß°ˇ(şô¸µ °ü·Ă) - ČŁĂâČÄ
	g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::CashItem_ENG_2 after call ms_pGFBillingRequest# %s RetErrCode(%d) \r\n", GetCharacterString(&m_character, string()), tmBRet.nRetErrCode);

	if(0 != tmBRet.nRetErrCode && GFERR_DB_SUCCESS != tmBRet.nRetErrCode)	// 2008-03-26 by cmkwon, ĽöÁ¤
	{
		if(i_pItem)
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_ENG_2_ Error(%d), |%s| ItemInfo(%8d:%s) TotalPrice(%d)\r\n"
				, tmBRet.nRetErrCode, GetCharacterString(GetCharacter(), string()), i_pItem->ItemNum, i_pItem->ItemName, i_nTotalPrice);
		}
		else
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_ENG_2_ Error(%d), |%s|\r\n"
				, tmBRet.nRetErrCode, GetCharacterString(GetCharacter(), string()));
		}
		switch(tmBRet.nRetErrCode)
		{
		case GFERR_DB_NOT_ENOUGH_CASH:				return ERR_CASH_mgQueryMall_RESULT_CANNOT_PAYMENT;
		case GFERR_DB_ACCT_INFO_CHECK_FAILED:		return ERR_CASH_mgQueryMall_RESULT_NO_ACCOUNT;
		case GFERR_DB_NONEXISTING_ITEM:				return ERR_CASH_INVALID_ITEM_INFORMATION;
		}

		return ERR_CASH_mgQueryMall_ERROR;
	}

	*o_pMCash		= tmBRet.nCashPoint;			// CashPoint
	*o_pGiftCard	= tmBRet.nBonusPoint;			// BonusPoint
	*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;		// Total Cash
	return ERR_NO_ERROR;
}
#endif // END - SERVICE_TYPE_ENGLISH_SERVER_2


