	if(g_pFieldGlobal->InMasangServer())
	{
		*o_pMCash		= 50000;																// CashPoint
		*o_pGiftCard	= (NULL == i_pItem) ? *o_pMCash : *o_pMCash - i_pItem->CashPrice;		// BonusPoint
		*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;												// Total Cash
		return ERR_NO_ERROR;
	}
