///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItemMoneyPay_Lin(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_EA)
/// \brief		// 2011-02-09 by shcho, ľĆ¸ŁÇîĆĽłŞ şô¸µ ˝Ă˝şĹŰ ±¸Çö -
///	\author		shcho			
/// \date		2011-02-09 ~
/// \warning	
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItemMoneyPay_Lin(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_EA)
{
#if defined(_DEBUG)
	if(g_pFieldGlobal->InMasangServer())
	{
		*o_pMCash		= 50000;					// CashPoint
		*o_pTotalMoney	= *o_pMCash;				// Total Cash
		return ERR_NO_ERROR;
	}
#endif

 	CODBCStatement odbcStmt;
	BOOL bRet = odbcStmt.Init(g_pFieldGlobal->GetBillingDBServerIP(), g_pFieldGlobal->GetBillingDBServerPort(), g_pFieldGlobal->GetBillingDBServerDatabaseName(), (LPSTR)g_pFieldGlobal->GetBillingDBServerUserID(), g_pFieldGlobal->GetBillingDBServerPassword(), g_pFieldGlobal->GetMainWndHandle());
	if (!bRet)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Billcrux connect error !!\r\n");
		return FALSE;
	}
	SQLHSTMT hstmt = odbcStmt.GetSTMTHandle();
	SQLRETURN ret = 0;
	SQLRETURN paramret = 0;
	int	returnCode = 0;

	SQLINTEGER arrCB[8] = {SQL_NTS,SQL_NTS,SQL_NTS,SQL_NTS,SQL_NTS,SQL_NTS,SQL_NTS,SQL_NTS}; 
	CHAR userID[ID_MAX_STR_LEN];
	MEMSET_ZERO(userID,sizeof(ID_MAX_STR_LEN));
	memcpy(userID,this->m_character.AccountName,strlen(this->m_character.AccountName)+1);
	// Äł˝¬ ĂĽĹ© ÇÁ·Î˝ĂŔú ˝ÇÇŕ ˝ĂŔŰ //
	ret = SQLBindParameter(hstmt, 1, SQL_PARAM_INPUT, SQL_C_CHAR, SQL_VARCHAR, ID_MAX_STR_LEN, 0, userID, 0,	&arrCB[0]);
	ret = SQLBindParameter(hstmt, 2, SQL_PARAM_OUTPUT, SQL_C_LONG, SQL_INTEGER, 0, 0, &returnCode, 0,	&arrCB[1]);
	ret = SQLBindParameter(hstmt, 3, SQL_PARAM_OUTPUT, SQL_C_LONG, SQL_INTEGER, 0, 0, o_pMCash, 0,	&arrCB[2]);
	
	bRet = odbcStmt.ExecuteQuery((char*)"{call dbo.procGetUserInfoByAceOnline(?,?,?)}");
	
	if(FALSE == bRet)
	{
		odbcStmt.ProcessLogMessagesForStmt("[DB Error] ExecuteQuery procGetUserInfoByAceOnline(?,?,?) Error !!\r\n");
		return TRUE;	// 2008-07-30 by cmkwon, Á¤»óĂł¸® 0, żˇ·Ż 1
	}

	SQLFreeStmt(hstmt, SQL_CLOSE);
	// Äł˝¬ ĂĽĹ© ÇÁ·Î˝ĂŔú ˝ÇÇŕ Áľ·á //
	
	// ąŢŔş ¸®ĹĎ ÄÚµĺżˇ °üÇŃ °ü·Ă żˇ·Ż ĂĽĹ©
	Err_t Errcode = 0;
	switch(returnCode)
	{
		case ARG_RETURN_SUCCESS:
#ifdef _DEBUG	// µđąö±× ˝Ăżˇ¸¸ µżŔŰÇŃ´Ů
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB EXCUTE] Errcode(%d) Success return!!\r\n", Errcode);
#endif
			break;

		case ERR_ARG_RETURN_INVALED_USER:		// »çżëŔÚ°ˇ ľĆ´Ô
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) INVALID USER!!\r\n", Errcode);
			return FALSE;

		case ERR_ARG_RETURN_NOT_NORMAL_USER:	// Á¤»ó ŔŻŔú°ˇ ľĆ´Ô
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) NOT_NOMAL USER!!\r\n", Errcode);
			return FALSE;

		default:								// ľËĽö ľř´Â żˇ·Ż
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) UNKNOWN ERROR!!\r\n", Errcode);
			return FALSE;

	}	
	*o_pTotalMoney = *o_pMCash;	// ş¸ż©ÁŮ ł˛Ŕş Äł˝¬


	// ľĆŔĚĹŰŔ» ±¸¸ĹÇŇ °ćżě
 	if(NULL != i_pItem)
 	{
		short GameID = ARG_GAME_SERVICE_ID;
		returnCode = 0;
		int transactionId = 0;
		// ±¸¸Ĺ ÇÁ·Î˝ĂŔú ˝ÇÇŕ ·çĆľ //
		arrCB[0]=arrCB[1]=arrCB[2]=arrCB[3]=arrCB[4]=arrCB[5]=arrCB[6]=arrCB[7]=SQL_NTS;
		ret = SQLBindParameter(hstmt, 1, SQL_PARAM_INPUT, SQL_C_CHAR,	SQL_VARCHAR, ID_MAX_STR_LEN, 0, userID, 0,	&arrCB[0]);
		ret = SQLBindParameter(hstmt, 2, SQL_PARAM_INPUT, SQL_C_SHORT, SQL_SMALLINT, 0, 0, &GameID, 0,	&arrCB[1]);
		ret = SQLBindParameter(hstmt, 3, SQL_PARAM_INPUT, SQL_C_LONG,	SQL_INTEGER, 0, 0, &i_pItem->ItemNum, 0,	&arrCB[2]);
		ret = SQLBindParameter(hstmt, 4, SQL_PARAM_INPUT, SQL_C_CHAR,	SQL_VARCHAR, ITEMNAME_MAX_STR_LEN, 0, i_pItem->ItemName, 0,	&arrCB[3]);
		ret = SQLBindParameter(hstmt, 5, SQL_PARAM_INPUT, SQL_C_LONG,	SQL_INTEGER, 0, 0, &i_pItem->CashPrice, 0,	&arrCB[4]);
		ret = SQLBindParameter(hstmt, 6, SQL_PARAM_OUTPUT, SQL_C_LONG,	SQL_INTEGER, 0, 0, &returnCode, 0,	&arrCB[5]);
		ret = SQLBindParameter(hstmt, 7, SQL_PARAM_OUTPUT, SQL_C_LONG,	SQL_INTEGER, 0, 0, &transactionId, 0,	&arrCB[6]);

		bRet = odbcStmt.ExecuteQuery((char*)"{call dbo.procOrderByAceOnline(?,?,?,?,?,?,?)}");
	
		if(FALSE == bRet)
		{
			odbcStmt.ProcessLogMessagesForStmt("[DB Error] ExecuteQuery dbo.procOrderByAceOnline(?,?,?,?,?,?,?) Error !!\r\n");
			return TRUE;	// 2008-07-30 by cmkwon, Á¤»óĂł¸® 0, żˇ·Ż 1
		}

		SQLFreeStmt(hstmt, SQL_CLOSE);
		// ±¸¸Ĺ ÇÁ·Î˝ĂŔú ˝ÇÇŕ Áľ·á //

		// ąŢŔş ¸®ĹĎ ÄÚµĺżˇ °üÇŃ °ü·Ă żˇ·Ż ĂĽĹ©
		switch(returnCode)
		{		
			case ARG_RETURN_SUCCESS:			// Á˘ĽÓ Ľş°ř
#ifdef _DEBUG	// µđąö±× ˝Ăżˇ¸¸ µżŔŰÇŃ´Ů
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB EXCUTE] Errcode(%d) Success return!!\r\n", Errcode);
#endif
				break;

			return FALSE;
			case ERR_ARG_RETURN_INVALED_USER:	// »çżëŔÚ°ˇ ľĆ´Ô
				g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) INVALID USER!!\r\n", Errcode);
				return FALSE;
				
			case ERR_ARG_RETURN_NOT_NORMAL_USER:	// Á¤»ó ŔŻŔú°ˇ ľĆ´Ô
				g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) NOT_NOMAL USER!!\r\n", Errcode);
				return FALSE;
				
			case ERR_ARG_RETURN_NOT_ENOUGH_CASH:	// ŔÜľ× şÎÁ·
				g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) ENOUGH_CASH!!\r\n", Errcode);
				return FALSE;
			default:								// ľËĽö ľř´Â żˇ·Ż
				g_pFieldGlobal->WriteSystemLogEX(TRUE, "[DB Error] Errcode(%d) UNKNOWN ERROR!!\r\n", Errcode);
		}	

		*o_pMCash = *o_pMCash - (i_pItem->CashPrice * 1);	// Äł˝¬ Â÷°¨
		*o_pTotalMoney = *o_pMCash;	// ş¸ż©ÁŮ ł˛Ŕş Äł˝¬
		
		// Äł˝¬ ľĆŔĚĹŰ ±¸¸Ĺ ·Î±×
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[CashItem] User(AccountUID = %d, AccountName = %s, CharacterUID = %d, CharacterName = %s)  Item(ItemNum = %d, CashPrice = %d, ItemCount = %d) \r\n"
			, m_character.AccountUniqueNumber, m_character.AccountName
			, m_character.CharacterUniqueNumber, m_character.CharacterName
			, i_pItem->ItemNum, i_pItem->CashPrice, 1);
		
 	}// if(NULL != i_pItem)
	
	return TRUE;
}
