///////////////////////////////////////////////////////////////////////////////
/// \fn			
/// \brief		// 2009-10-06 by cmkwon, şŁĆ®ł˛ °ÔŔÓ °ˇµĺ X-TRAPŔ¸·Î şŻ°ć - 
/// \author		cmkwon
/// \date		2009-10-08 ~ 2009-10-08
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::XTrapLoadMapFile(const char *i_szDir, char *i_szPrefixFileName)
{
	BYTE			arrXTrapMap[XTRAP_CSFILE_NUM][XTRAP_CS4_BUFSIZE_MAP];
	int				nLoadedCnt = 0;

	vectstring		vectFileNameList;

	MEMSET_ZERO(arrXTrapMap, XTRAP_CSFILE_NUM * XTRAP_CS4_BUFSIZE_MAP);
	
	// 2009-10-08 by cmkwon, ÇŘ´ç Ćú´őŔÇ ¸đµç ĆÄŔĎ ¸®˝şĆ®¸¦ °ˇÁ®żÂ´Ů
	if(FALSE == CFieldIOCP::GetAllFileNameList(&vectFileNameList, i_szDir, i_szPrefixFileName))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::XTrapLoadMapFile#  call CFieldIOCP::GetAllFileNameList# error !!, Directory(%s) ListCnt(%d) \r\n", i_szDir, vectFileNameList.size());
		return FALSE;
	}
	if(XTRAP_CSFILE_NUM > vectFileNameList.size())
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::XTrapLoadMapFile#  mapfile count error !!, ReqCount(%d) fileCount(%d) \r\n", XTRAP_CSFILE_NUM, vectFileNameList.size());
		return FALSE;
	}
	
	// 2009-10-08 by cmkwon, Á¤·ÄŔ» Ŕ§ÇŘ ´ëą®ŔÚ·Î ¸đµÎ şŻ°ć
	for_each(vectFileNameList.begin(), vectFileNameList.end(), for_each_uprcase_at_string());

	// 2009-10-08 by cmkwon, Á¤·Ä
	sort(vectFileNameList.begin(), vectFileNameList.end(), greater<string>());

	vectstring::iterator itr(vectFileNameList.begin());
	for(; itr != vectFileNameList.end(); itr++)
	{
		string *pstrFileName = itr;
		
		char		szFilePathMap[MAX_PATH];
		FILE		*fpMap = NULL;
		sprintf(szFilePathMap, "%s\\%s", i_szDir, pstrFileName->c_str());

		fpMap = fopen(szFilePathMap, "rb");
		if(NULL == fpMap)
		{
			char szCurDir[MAX_PATH];
			GetCurrentDirectory(MAX_PATH, szCurDir);
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "\r\n[Error] CFieldIOCPSocket::XTrapLoadMapFile# fopen error !! Path(%s), CurDir(%s)\r\n", szFilePathMap, szCurDir);
			return FALSE;
		}

		DWORD dwReadCnt = fread(arrXTrapMap[nLoadedCnt], XTRAP_CS4_BUFSIZE_MAP, 1, fpMap);
		fclose(fpMap);
		if(0 == dwReadCnt)
		{
			char szCurDir[MAX_PATH];
			GetCurrentDirectory(MAX_PATH, szCurDir);
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "\r\n[Error] CFieldIOCPSocket::XTrapLoadMapFile# fread error !! Path(%s), CurDir(%s), readCnt(%d) \r\n", szFilePathMap, szCurDir, dwReadCnt);
			return FALSE;
		}
		nLoadedCnt++;

		if(XTRAP_CSFILE_NUM <= nLoadedCnt)
		{
			break;
		}
	}

	if(XTRAP_CSFILE_NUM != nLoadedCnt)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::XTrapLoadMapFile#  loaded mapfile count error !!, ReqCount(%d) fileCount(%d) loadedCount(%d) \r\n", XTRAP_CSFILE_NUM, vectFileNameList.size(), nLoadedCnt);
		return FALSE;
	}

	memcpy(ms_XTrapMap, arrXTrapMap, XTRAP_CSFILE_NUM * XTRAP_CS4_BUFSIZE_MAP);
	return TRUE;
}

