///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItemMoneyPay_Yetime_Chn(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_nTotalPrice/*=0*/)
/// \brief		// 2007-08-22 by cmkwon, Áß±ą Yetime şô¸µ ¶óŔĚşę·Ż¸® Ŕűżë - ÇÔĽö Ăß°ˇ
/// \author		cmkwon
/// \date		2007-08-22 ~ 2007-08-22
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItemMoneyPay_Yetime_Chn(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, int i_nTotalPrice/*=0*/)
{
#if defined(_DEBUG)
	///////////////////////////////////////////////////////////////////////////////
	// 2009-03-02 by cmkwon, ł»şÎ Ĺ×Ľ·żˇĽ­ Äł˝¬ Ć÷ŔÎĆ® °ü·Ă ĽöÁ¤(µđąö±× ¸đµĺ˝Ă¸¸ µżŔŰ) - Áß±ą Yetime Ăł¸®
	if(g_pFieldGlobal->InMasangServer())
	{
		*o_pMCash		= 50000;																// CashPoint
		*o_pGiftCard	= (NULL == i_pItem) ? *o_pMCash : *o_pMCash - i_pItem->CashPrice;		// BonusPoint
		*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;												// Total Cash
		return ERR_NO_ERROR;
	}
#endif
	
	*o_pTotalMoney		= 0;
	*o_pMCash			= 0;
	*o_pGiftCard		= 0;

	int nCurTotalMoney = 0;	
	Err_t err = 0;
	char szErrString[1024];
	STRNCPY_MEMSET(szErrString, "No Error", 1024);

	if(NULL == i_pItem)
	{
		err = BillingPayW_Yetime_Chn(&nCurTotalMoney, szErrString, g_pFieldGlobal->GetServerGroupName(), m_character.AccountName
										, m_character.CharacterName);
	}
	else
	{
		err = BillingPayW_Yetime_Chn(&nCurTotalMoney, szErrString, g_pFieldGlobal->GetServerGroupName(), m_character.AccountName
										, m_character.CharacterName, i_pItem->ItemNum, 1, i_nTotalPrice);
	}

	if(ERR_NO_ERROR == err)
	{
		*o_pTotalMoney		= nCurTotalMoney;
		*o_pMCash			= nCurTotalMoney;
	}
	else
	{
		if(NULL == i_pItem)
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]: BillingPayW_Yetime_Chn error!!, %s, Err(%d:%s) ErrString(%s)\r\n"
				, GetCharacterString(&m_character, string()), err, GetErrorString(err), szErrString);
		}
		else
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]: BillingPayW_Yetime_Chn error!!, %s, Err(%d:%s) ErrString(%s), ItemInfo(%d:%s) BuyCount(%d), BuyTotalMoney(%d)\r\n"
				, GetCharacterString(&m_character, string()), err, GetErrorString(err), szErrString, i_pItem->ItemNum, i_pItem->ItemName, 1, i_nTotalPrice);
		}
	}

	return err;
}
