	tmBReq.nCommand			= 1;					// 2006-09-13 by cmkwon, ŔÜľ× Á¶Č¸
	tmBReq.nGameUID			= MSBILLING_GAMEUID;	// 2006-09-13 by cmkwon, GameUID
	STRNCPY_MEMSET(tmBReq.szAccountName, m_character.AccountName, SIZE_MAX_ACCOUNT_NAME);
