_FUNC_S_REC	CFieldIOCPSocket::ms_pfRec4Apex		= NULL;		// 2009-11-04 by cmkwon, ĹÂ±ą °ÔŔÓ°ˇµĺ Apex·Î şŻ°ć - 

///////////////////////////////////////////////////////////////////////////////
/// \fn			
/// \brief		// 2009-11-04 by cmkwon, ĹÂ±ą °ÔŔÓ°ˇµĺ Apex·Î şŻ°ć - 
/// \author		cmkwon
/// \date		2009-11-04 ~ 2009-11-04
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
long CFieldIOCPSocket::SecurityApexSendData(int i_nCliIdx, const char *i_pBuff, int i_nBuffLen)
{
	CFieldIOCPSocket *pFISoc = ms_pFieldIOCP->GetFieldIOCPSocket(i_nCliIdx);
	if(NULL == pFISoc
		|| FALSE == pFISoc->IsValidCharacter(FALSE, TRUE))	// 2010-04-22 by cmkwon, ľĆ·ąłŞ ÇĂ·ąŔĚ »óĹÂµµ ŔŻČżÇŃ Äł¸ŻĹÍ·Î Ăł¸® - 
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::SecurityApexSendData# FSocket invalid !! ClientIdx(%d) \r\n", i_nCliIdx);
		return -1;
	}
	
// 2009-11-04 by cmkwon, ŔÓ˝Ăżë
//	g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [TEMP] 091104 CFieldIOCPSocket::SecurityApexSendData# %s BufLen(%d) \r\n", GetCharacterString(pFISoc->GetCharacter(), string()), i_nBuffLen);

	INIT_MSG_WITH_BUFFER(MSG_FC_MOVE_APEX_REQ_APEXDATA, T_FC_MOVE_APEX_REQ_APEXDATA, pSMsg, SendBuf);
	pSMsg->cMsgType			= SECURITY_APEX_Cmd_ApexData;
	pSMsg->nApexDataLen		= i_nBuffLen;
	memcpy(pSMsg->szApexData, i_pBuff, min(i_nBuffLen, SECURITY_APEX_MaxPacketLen));	
	if(FALSE == pFISoc->SendAddData(SendBuf, MSG_SIZE(MSG_FC_MOVE_APEX_REQ_APEXDATA)))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::SecurityApexSendData# fail to send !! ClientIdx(%d) \r\n", i_nCliIdx);
		return -1;
	}

	return 0;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			
/// \brief		// 2009-11-04 by cmkwon, ĹÂ±ą °ÔŔÓ°ˇµĺ Apex·Î şŻ°ć - 
/// \author		cmkwon
/// \date		2009-11-04 ~ 2009-11-04
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
long CFieldIOCPSocket::SecurityApexKillUser(int i_nCliIdx, int i_nActon)
{
	CFieldIOCPSocket *pFISoc = ms_pFieldIOCP->GetFieldIOCPSocket(i_nCliIdx);
	if(NULL == pFISoc
		|| FALSE == pFISoc->IsUsing())
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::SecurityApexKillUser# FSocket invalid !! ClientIdx(%d) \r\n", i_nCliIdx);
		return -1;
	}
		
	g_pFieldGlobal->WriteSystemLogEX(TRUE, "  [Notify] CFieldIOCPSocket::SecurityApexKillUser# kill user !! %s Action(%d) \r\n", GetCharacterString(pFISoc->GetCharacter(), string()), i_nActon);
	pFISoc->Close(0x14065);
	return 0;
}
#endif // END - #if defined(SERVICE_TYPE_THAI_SERVER_1) // 2009-11-04 by cmkwon, ĹÂ±ą °ÔŔÓ°ˇµĺ Apex·Î şŻ°ć - 


