///////////////////////////////////////////////////////////////////////////////
/// \fn			
/// \brief		// 2009-08-18 by cmkwon, żą´ç Äł˝¬Ţ şí·° °čÁ¤ ĂĽĹ© Ăß°ˇ - CFieldIOCPSocket::CashItem_Yedang_CheckAccount_byHTTP
/// \author		cmkwon
/// \date		2009-08-18 ~ 2009-08-18
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::CashItem_Yedang_CheckAccount_byHTTP(char * i_szTargetAccName)
{
	///////////////////////////////////////////////////////////////////////////////
	// ·Î±×ŔÎÇĎ´Â °ÔŔÓÄÚµĺ
	//	PT1= 1, clubAudition= 2, PT2= 3, AceOnline= 4, paeOnline= 7, PT3= 8, BandMaster= 9
	GenericHTTPClient httpCli;	
    httpCli.InitilizePostArguments();
	httpCli.AddPostArguments("userID", i_szTargetAccName);
	httpCli.AddPostArguments("gameID", 4);
	
	static char *szServURL	= "gpUserAuth.ydonline.com";
	static int nServPort	= 8789;
	char szURL[1024];
	sprintf(szURL, "http://%s:%d/gpUserInfo.asmx/GetBlockUserChk_UserID", szServURL, nServPort);
	BOOL bRet = httpCli.Request(szURL, GenericHTTPClient::RequestPostMethod);
	if(FALSE == bRet)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_Yedang_CheckAccount_byHTTP# call Request fail !!, %s URL(%s) \r\n"
			, GetCharacterString(this->GetCharacter(), string()), szURL);
		return FALSE;
	}
	
    LPCTSTR szResponseMsg = httpCli.QueryHTTPResponse();
	if(0 >= strlen(szResponseMsg))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_Yedang_CheckAccount_byHTTP# no response message !!, %s URL(%s) \r\n"
			, GetCharacterString(this->GetCharacter(), string()), szURL);
		return FALSE;
	}
	int nErrCode = httpCli.LoadXMLFromQueryHTTPResponse();
	if(0 != nErrCode)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_Yedang_CheckAccount_byHTTP# loadXML fail 1 !!, %s URL(%s) ResponseMsg(%s), ErrCode(%d)\r\n"
			, GetCharacterString(this->GetCharacter(), string()), szURL, szResponseMsg, nErrCode);
		return FALSE;
	}
	
	char szSpReturnNo[1024];
	MEMSET_ZERO(szSpReturnNo, 1024);
	if(FALSE == httpCli.GetTextFromXMLLoaderByNodeName(szSpReturnNo, 1024, "//int"))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 2!!, URL(%s), %s, ResponseMsg(%s)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), szResponseMsg);
		return FALSE;
	}

	// -1 ŔĚ¸é Á¤»ó °čÁ¤, 1ŔĚ¸é şí·° °čÁ¤ ==> ±×·ŻąÇ·Î -1ŔĚ ľĆ´Ď¸é żˇ·Ż¸¦ ¸®ĹĎÇĎż© Ľ±ą° şŇ°ˇ Ăł¸®
	int nSpReturnNo = atoi(szSpReturnNo);
	if(-1 != nSpReturnNo)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 3!!, URL(%s), %s, SpReturnNo(%d)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), nSpReturnNo);
		return FALSE;
	}
	
	return TRUE;
}

