///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItem_Netpower(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, INT i_nItemCount/*=0*/)
/// \brief		// 2008-09-23 by cmkwon, Áöżř Ľ­şń˝ş Ăß°ˇ(´ë¸¸ Netpower_Tpe) - 
/// \author		cmkwon
/// \date		2008-09-23 ~ 2008-09-23
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItem_Netpower(INT *o_pTotalMoney, INT *o_pMCash, INT *o_pGiftCard, ITEM *i_pItem/*=NULL*/, INT i_nItemCount/*=0*/)
{
#if defined(_DEBUG)
	///////////////////////////////////////////////////////////////////////////////
	// 2009-03-02 by cmkwon, ł»şÎ Ĺ×Ľ·żˇĽ­ Äł˝¬ Ć÷ŔÎĆ® °ü·Ă ĽöÁ¤(µđąö±× ¸đµĺ˝Ă¸¸ µżŔŰ) - ´ë¸¸ Netpower Ăł¸®
	if(g_pFieldGlobal->InMasangServer())
	{
		*o_pMCash		= 50000;																// CashPoint
		*o_pGiftCard	= (NULL == i_pItem) ? *o_pMCash : *o_pMCash - i_pItem->CashPrice;		// BonusPoint
		*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;												// Total Cash
		return ERR_NO_ERROR;
	}
#endif

	SNETBILL_REQ_DATA	tmBReq;		MEMSET_ZERO(&tmBReq, sizeof(tmBReq));
	SNETBILL_RET_DATA	tmBRet;		MEMSET_ZERO(&tmBRet, sizeof(tmBRet));
	
	tmBReq.nCommand			= 1;					// 2008-11-13 by cmkwon, ±âş»°ŞŔş ŔÜľ×Á¶Č¸ - // ¸í·ÉÁľ·ů(1:ŔÜľ×Á¶Č¸, 2:ľĆŔĚĹŰ±¸¸Ĺ)
	STRNCPY_MEMSET(tmBReq.szAccountName, m_character.AccountName, SIZE_MAX_ACCOUNT_NAME);
	STRNCPY_MEMSET(tmBReq.szCharacterName, m_character.CharacterName, SIZE_MAX_CHARACTER_NAME);
	STRNCPY_MEMSET(tmBReq.szUserIP, GetPeerIP(), SIZE_MAX_IPADDRESS);
	if(i_pItem)
	{// if buy item
		
		tmBReq.nCommand				= 2;			// 2008-11-13 by cmkwon, ľĆŔĚĹŰ ±¸¸Ĺ
		sprintf(tmBReq.szItemNum, "%d", i_pItem->ItemNum);
		STRNCPY_MEMSET(tmBReq.szItemName, i_pItem->ItemName, SIZE_MAX_ITEM_NAME);
		tmBReq.nBuyItemCount		= 1;					// ±¸¸Ĺ Ä«żîĆ®
		tmBReq.nItemUnitPrice		= i_pItem->CashPrice;	// 1°ł´ç °ˇ°Ý		
	}
	
	Err_t nErrCode = CashItem_Netpower_byHTTP(&tmBReq, &tmBRet);	
	if(0 != nErrCode)
	{
		if(i_pItem)
		{			
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_Netpower# CashItem_Netpower_byHTTP error(%d), %s ItemInfo(%d:%s) ItemPrice(%d) RetCode(%d, %d)\r\n"
				, tmBRet.nRetErrCode, GetCharacterString(&m_character, string()), i_pItem->ItemNum, i_pItem->ItemName, tmBReq.nItemUnitPrice, nErrCode, tmBRet.nRetErrCode);
		}
		else
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] CFieldIOCPSocket::CashItem_Netpower# CashItem_Netpower_byHTTP error(%d), %s RetCode(%d, %d)\r\n"
				, tmBRet.nRetErrCode, GetCharacterString(&m_character, string()), nErrCode, tmBRet.nRetErrCode);
		}
		return tmBRet.nRetErrCode;
	}
	
	*o_pMCash		= tmBRet.nCashPoint;					// RealCash
	*o_pGiftCard	= tmBRet.nBonusPoint;					// BonusCash
	*o_pTotalMoney	= *o_pMCash + *o_pGiftCard;				// Total Cash
	
	return ERR_NO_ERROR;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItem_Netpower_byHTTP(SNETBILL_REQ_DATA *i_pReqData, SNETBILL_RET_DATA *o_pRetData)
/// \brief		// 2008-11-13 by cmkwon, ´ë¸¸ Netpower_Tpe şô¸µ ˝Ă˝şĹŰ ±¸Ăŕ - 
/// \author		cmkwon
/// \date		2008-11-13 ~ 2008-11-13
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItem_Netpower_byHTTP(SNETBILL_REQ_DATA *i_pReqData, SNETBILL_RET_DATA *o_pRetData)
{
	switch(i_pReqData->nCommand)
	{
	case 1:
		{
			return this->CashItem_Netpower_byHTTP_GetCashPoint(i_pReqData, o_pRetData);
		}
		break;
	case 2:
		{
			return this->CashItem_Netpower_byHTTP_BuyCashItem(i_pReqData, o_pRetData);
		}
		break;
	}

	o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
	return o_pRetData->nRetErrCode;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			Err_t CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint(SNETBILL_REQ_DATA *i_pReqData, SNETBILL_RET_DATA *o_pRetData)
/// \brief		// 2008-11-13 by cmkwon, ´ë¸¸ Netpower_Tpe şô¸µ ˝Ă˝şĹŰ ±¸Ăŕ - 
/// \author		cmkwon
/// \date		2008-11-13 ~ 2008-11-13
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
Err_t CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint(SNETBILL_REQ_DATA *i_pReqData, SNETBILL_RET_DATA *o_pRetData)
{
	GenericHTTPClient httpCli;	
    httpCli.InitilizePostArguments();
	httpCli.AddPostArguments("memberNo", this->GetCharacter()->AccountName);
	httpCli.AddPostArguments("serviceCode", NETBILL_SERVICE_CODE_FOR_BILLING);		// 00001->µĄÄ«·Đ, 00002->Ľ­µçľîĹĂ, 00003->ACEonline

	char szURL[1024];
	sprintf(szURL, "http://%s:%d/GameServerInterface.asmx/GetUserCashAmount", g_pFieldGlobal->GetBillingDBServerIP(), g_pFieldGlobal->GetBillingDBServerPort());
	BOOL bRet = httpCli.Request(szURL, GenericHTTPClient::RequestPostMethod);
	if(FALSE == bRet)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# call Request fail !!, URL(%s), %s\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()));
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	
    LPCTSTR szResponseMsg = httpCli.QueryHTTPResponse();
	if(0 >= strlen(szResponseMsg))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# no response message !!, URL(%s), %s\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()));
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	int nErrCode = httpCli.LoadXMLFromQueryHTTPResponse();
	if(0 != nErrCode)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 1!!, URL(%s), %s, ResponseMsg(%s), ErrCode(%d)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), szResponseMsg, nErrCode);
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	
	char szSpReturnNo[1024];
	MEMSET_ZERO(szSpReturnNo, 1024);
	if(FALSE == httpCli.GetTextFromXMLLoaderByNodeName(szSpReturnNo, 1024, "//SpReturnNo"))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 2!!, URL(%s), %s, ResponseMsg(%s)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), szResponseMsg);
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	int nSpReturnNo = atoi(szSpReturnNo);
	if(0 != nSpReturnNo)
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 3!!, URL(%s), %s, SpReturnNo(%d)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), nSpReturnNo);
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	
	char szRemainedBalanceAmount[1024];
	MEMSET_ZERO(szRemainedBalanceAmount, 1024);
	if(FALSE == httpCli.GetTextFromXMLLoaderByNodeName(szRemainedBalanceAmount, 1024, "//RemainedBalanceAmount"))
	{
		g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR]CFieldIOCPSocket::CashItem_Netpower_byHTTP_GetCashPoint# loadXML fail 4!!, URL(%s), %s, ResponseMsg(%s)\r\n"
			, szURL, GetCharacterString(this->GetCharacter(), string()), szResponseMsg);
		o_pRetData->nRetErrCode	= ERR_CASH_NORMAL_ERROR;
		return o_pRetData->nRetErrCode;
	}
	
	o_pRetData->nCashPoint		= atoi(szRemainedBalanceAmount);
	o_pRetData->nRetErrCode		= ERR_NO_ERROR;
	return o_pRetData->nRetErrCode;
}

