	httpCli.AddPostArguments("billGoodsCode", "");										// żä±ÝÁ¦ ÄÚµĺ
	httpCli.AddPostArguments("serverCode", "");											// Ľ­ąö ÄÚµĺ
	httpCli.AddPostArguments("connectionNo", "");										// °ÔŔÓ Á˘ĽÓ ąřČŁ
	httpCli.AddPostArguments("pcbangNo", "");											// ÇÇľľąć ąřČŁ
	httpCli.AddPostArguments("agencyNo", "");											// ĂŃĆÇ ąřČŁ
	httpCli.AddPostArguments("note", i_pReqData->szItemName);							// şń°í (ş¸ĹëŔş ľĆŔĚĹŰ¸í)
	httpCli.AddPostArguments("payPassword", "");										// ±¸¸Ĺ şńąĐ ąřČŁ[MD5 Hashed String], »çżëÇĎÁö ľĘ´Â Ľ­şń˝ş¶ó¸é Empty String
	httpCli.AddPostArguments("period", "0");											// ±â°ŁÁ¦ ľĆŔĚĹŰ ŔŻČż±â°Ł(ĂĘ) [µĄÄ«·Đ Ŕüżë. ż©Ĺ¸°ÔŔÓŔş 0]
	httpCli.AddPostArguments("itemIndex", "0");											// ±¸¸Ĺ´ë»ó ľĆŔĚĹŰ ŔÎµ¦˝ş [µĄÄ«·Đ Ŕüżë. ż©Ĺ¸°ÔŔÓŔş 0]
	httpCli.AddPostArguments("itemName", "");											// ±¸¸Ĺ´ë»ó ľĆŔĚĹŰ ¸í [µĄÄ«·Đ Ŕüżë. ż©Ĺ¸°ÔŔÓŔş Empty String]
	httpCli.AddPostArguments("itemSerialNo", "");										// ±¸¸Ĺ´ë»ó ľĆŔĚĹŰ ˝Ă¸®ľó [µĄÄ«·Đ Ŕüżë. ż©Ĺ¸°ÔŔÓŔş Empty String]

	
	char szURL[1024];
