///////////////////////////////////////////////////////////////////////////////
/// \fn			BOOL CFieldIOCPSocket::IsChargeUser(void)
/// \brief		
/// \author		cmkwon
/// \date		2006-06-01 ~ 2006-06-01
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::IsChargeUser(void)
{
	switch(g_pFieldGlobal->GetLanguageType())
	{
	case LANGUAGE_TYPE_VIETNAMESE:
		{
			if(m_ItemManager.IsExistPremiumCard())
			{// 2006-06-01 by cmkwon, şŁĆ®ł˛Ŕş ÇÁ¸®ąĚľöŔ¸·Î Á¤ľ×Á¦¸¦ ĂĽĹ©ÇŃ´Ů.
				return TRUE;
			}
		}
		break;
	default:
		{
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CFieldIOCPSocket::IsValidGameUser(Experience_t *o_pExptMaxEXP/*=NULL*/
									   , Experience_t i_CurEXP/*=0.0f*/)
{
	///////////////////////////////////////////////////////////////////////////////
	// 2006-10-21 by cmkwon, şŁĆ®ł˛µµ ÇŃ±ąąöÁŻ°ú µżŔĎÇĎ°Ô Ľ­şń˝ş ÁřÇŕ
	return TRUE;


	if(IsChargeUser())
	{
		return TRUE;
	}

	switch(g_pFieldGlobal->GetLanguageType())
	{
	case LANGUAGE_TYPE_VIETNAMESE:
		{
			///////////////////////////////////////////////////////////////////////////////
			// 2006-06-14 by cmkwon, °čÁ¤ µî·ĎŔĎ ĂĽĹ©
			ATUM_DATE_TIME tmaExpre = m_AccountRegisteredDate;
			tmaExpre.AddDateTime(0, 0, 7, 0, 0, 0);
			ATUM_DATE_TIME tmaCur(TRUE);
			if(tmaExpre < tmaCur)
			{
				return FALSE;
			}

			///////////////////////////////////////////////////////////////////////////////
			// 2006-06-14 by cmkwon, °ćÇčÄˇ ĂĽĹ©
			if(0.0f >= i_CurEXP)
			{
				i_CurEXP = m_character.Experience;
			}
			Experience_t tmExp = CAtumSJ::GetExperienceFromPercentage(99, 24);
			if(i_CurEXP >= tmExp)
			{
				if(o_pExptMaxEXP)
				{
					*o_pExptMaxEXP = tmExp;
				}
				return FALSE;
			}
		}
		break;
	}

	return TRUE;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			BOOL CFieldIOCPSocket::LoadCashLibrary(void)
/// \brief		// 2008-03-17 by cmkwon, Gameforge4D_Eng şô¸µ ¸đµâ ż¬µżÇĎ±â - 
/// \author		cmkwon
/// \date		2008-03-17 ~ 2008-03-17
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::LoadCashLibrary(void)
{
	
// 2008-07-11 by cmkwon, Gameforge4D_Deu şô¸µ ¸đµâ ż¬µżÇĎ±â - 
// 2008-12-22 by cmkwon, Áöżř Ľ­şń˝ş Ăß°ˇ(Gameforge4D ĹÍĹ°ľĆ, şŇľî, ŔĚĹ»¸®ľĆľî) - ľĆ·ˇżÍ °°ŔĚ 3°ł Ľ­şń˝ş Ăß°ˇ
//#if defined(SERVICE_TYPE_ENGLISH_SERVER_2) || defined(SERVICE_TYPE_GERMAN_SERVER_1)
// 2009-06-04 by cmkwon, Áöżř Ľ­şń˝ş Ăß°ˇ(Gameforge4D Ćú¶őµĺľî, ˝şĆäŔÎľî) - 
//#if defined(SERVICE_TYPE_ENGLISH_SERVER_2) || defined(SERVICE_TYPE_GERMAN_SERVER_1) || defined(SERVICE_TYPE_TURKISH_SERVER_1) || defined(SERVICE_TYPE_FRENCH_SERVER_1) || defined(SERVICE_TYPE_ITALIAN_SERVER_1)
#if defined(SERVICE_TYPE_ENGLISH_SERVER_2) || defined(SERVICE_TYPE_GERMAN_SERVER_1) || defined(SERVICE_TYPE_TURKISH_SERVER_1) || defined(SERVICE_TYPE_FRENCH_SERVER_1) || defined(SERVICE_TYPE_ITALIAN_SERVER_1) || defined(SERVICE_TYPE_POLISH_SERVER_1) || defined(SERVICE_TYPE_SPANISH_SERVER_1)

	// 2008-03-17 by cmkwon, Gameforge4D_Eng şô¸µ ¸đµâ ż¬µżÇĎ±â - ¶óŔĚşę·Ż¸® ĂĘ±âČ­
	if(NULL != ms_hBillingLibrary)
	{
		return TRUE;
	}
	
	ms_hBillingLibrary = LoadLibrary("flysisdll.dll");
	if ((UINT)ms_hBillingLibrary < HINSTANCE_ERROR)
	{
		ms_hBillingLibrary = NULL;
		return FALSE;
	}
	
	ms_pGFBillingRequest = (PGFBILLINGREQUEST) GetProcAddress((HMODULE)ms_hBillingLibrary, "GFBillingReqExecute");
	return TRUE;
#endif // END - SERVICE_TYPE_ENGLISH_SERVER_2
	
	return TRUE;
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::UnloadCashLibrary(void)
/// \brief		// 2008-03-17 by cmkwon, Gameforge4D_Eng şô¸µ ¸đµâ ż¬µżÇĎ±â - 
/// \author		cmkwon
/// \date		2008-03-17 ~ 2008-03-17
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::UnloadCashLibrary(void)
{
	if(ms_hBillingLibrary)
	{
		FreeLibrary((HMODULE)ms_hBillingLibrary);
		ms_hBillingLibrary	= NULL;
	}
}

