/// \fn			BOOL CFieldIOCPSocket::CheckMemoryHackByMemoryHackCheckTy(ITEM_GENERAL *i_pItemGen, int i_nMemoryHackCheckTy, float i_fValidValue, float i_fCurrentValue, int i_nParam1/*=0*/)
/// \brief		
/// \author		cmkwon
/// \date		2005-12-21 ~ 2005-12-21
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
char * GetChatTypeString(int nType)//changed hack type representation to text 28-08-2020 by Inet
{
	switch(nType)
	{
	case HACK_CHECK_TYPE_SHOTNUM:
		return "HACK_CHECK_TYPE_SHOTNUM";
	case HACK_CHECK_TYPE_MULTINUM:
		return "HACK_CHECK_TYPE_MULTINUM";
	case HACK_CHECK_TYPE_REATTACKTIME:
		return "HACK_CHECK_TYPE_REATTACKTIME";
	case HACK_CHECK_TYPE_REPEATTIME:
		return "HACK_CHECK_TYPE_REPEATTIME";
	case HACK_CHECK_TYPE_TIME:
		return "HACK_CHECK_TYPE_TIME";
	case HACK_CHECK_TYPE_RANGEANGLE:
		return "HACK_CHECK_TYPE_RANGEANGLE";
	case HACK_CHECK_TYPE_BOOSTERANGLE:
		return "HACK_CHECK_TYPE_BOOSTERANGLE";
	case HACK_CHECK_TYPE_ORBITTYPE:
		return "HACK_CHECK_TYPE_ORBITTYPE";
	case HACK_CHECK_TYPE_ABILITYMIN:
		return "HACK_CHECK_TYPE_ABILITYMIN";
	case HACK_CHECK_TYPE_ABILITYMAX:
		return "HACK_CHECK_TYPE_ABILITYMAX";
	case HACK_CHECK_TYPE_SPEEDPENALTY:
		return "HACK_CHECK_TYPE_SPEEDPENALTY";
	case HACK_CHECK_TYPE_RANGE:
		return "HACK_CHECK_TYPE_RANGE";
	case HACK_CHECK_TYPE_TRANSPORT:
		return "HACK_CHECK_TYPE_TRANSPORT";
	case HACK_CHECK_TYPE_TOTALWEIGHT:
		return "HACK_CHECK_TYPE_TOTALWEIGHT";
	case HACK_CHECK_TYPE_POSITION:
		return "HACK_CHECK_TYPE_POSITION";
	case HACK_CHECK_TYPE_MAP_CHECK_SUM:
		return "HACK_CHECK_TYPE_MAP_CHECK_SUM";
	case HACK_CHECK_TYPE_RESOBJ_CHECK_SUM:
		return "HACK_CHECK_TYPE_RESOBJ_CHECK_SUM";
	default:
		return "Unknown";
	}
}
BOOL CFieldIOCPSocket::CheckMemoryHackByMemoryHackCheckTy(ITEM_GENERAL *i_pItemGen, int i_nMemoryHackCheckTy
														  , float i_fValidValue, float i_fCurrentValue, int i_nParam1/*=0*/)
{
	//09-05-2020 by Inetpub

	const auto fReaTolerance = 0.025f;
	const auto fIntTolerance = 1.0f;

	auto bIsSame = true;

	if (!i_pItemGen || i_pItemGen == NULL) {
		CFieldGlobal::WriteSystemLogEX(TRUE, "Inetpub_Anticheat :: CheckMemoryHackByMemoryHackCheckTy => !i_pItemGen\r\n");
		return TRUE;
	}

	switch (i_nMemoryHackCheckTy)
	{
		//false positives improoved by Inet 28-08-2020
	case HACK_CHECK_TYPE_REATTACKTIME: //for false positives 28-08-2020
	case HACK_CHECK_TYPE_RANGEANGLE: //false positives 29-08-2020
		{
			if(i_fCurrentValue < i_fValidValue)
			{
				bIsSame = fabs(i_fValidValue - i_fCurrentValue) < fReaTolerance;
			}
		}
		break;
	case HACK_CHECK_TYPE_MULTINUM://for false positives 28-08-2020
	case HACK_CHECK_TYPE_SHOTNUM://for false positives 28-08-2020
		{
			if (i_fCurrentValue > i_fValidValue)
			{
				bIsSame = fabs(i_fValidValue - i_fCurrentValue) < fIntTolerance;
			}
		}
		break;
	case HACK_CHECK_TYPE_RANGE:
	case HACK_CHECK_TYPE_TIME:	
	case HACK_CHECK_TYPE_BOOSTERANGLE:
	case HACK_CHECK_TYPE_ABILITYMIN:
	case HACK_CHECK_TYPE_ABILITYMAX:
	{
		bIsSame = fabs(i_fValidValue - i_fCurrentValue) < fReaTolerance;
	}
	break;
	case HACK_CHECK_TYPE_POSITION:
	{
		bIsSame = true;
	}
	break;
	default:
	{
		bIsSame = fabs(i_fValidValue - i_fCurrentValue) < fIntTolerance;
	}
	break;

	}

	if (!bIsSame) {
		this->m_nInetAnticheatHackTimes++;
		
		CFieldGlobal::WriteSystemLogEX(TRUE, "========= Anticheat by Inetpub v2 =========\r\n");
		CFieldGlobal::WriteSystemLogEX(TRUE, "Inetpub_Anticheat :: Detected hack type(%s) Valid(%.2f) Current(%.2f) ItemUID(%I64d)\r\n", GetChatTypeString(i_nMemoryHackCheckTy), i_fValidValue, i_fCurrentValue, i_pItemGen->UniqueNumber);
		if (this->m_nInetAnticheatHackTimes >= 3) {
			if (COMPARE_RACE(this->m_character.Race, RACE_OPERATION | RACE_GAMEMASTER | RACE_MONITOR)) {
				CFieldGlobal::WriteSystemLogEX(TRUE, "	 => Staff hack detected! (CN: %s [AccNm: %s]) IP: %s \r\n", this->m_character.CharacterName, this->m_character.AccountName, this->GetPeerIP());
			}
			else {
				CFieldGlobal::WriteSystemLogEX(TRUE, "	 => Player hack detected! (CN: %s [AccNm: %s]) IP: %s \r\n", this->m_character.CharacterName, this->m_character.AccountName, this->GetPeerIP());
				CFieldGlobal::WriteSystemLogEX(TRUE, "	 => Player KICKED \r\n");

				this->Close(0x001, FALSE, 3000);
			}
			return FALSE;
		}
		CFieldGlobal::WriteSystemLogEX(TRUE, "============ End of Anticheat ============\r\n");
	}

	return TRUE;
}

void CFieldIOCPSocket::InsertAttackTargetIndexVector(ClientIndex_t i_Index)
{
	if(FALSE == IS_MONSTER_CLIENT_INDEX(i_Index))
	{// 2009-12-11 by cmkwon, µĄąĚÁö ľî±×·Î·Î Ĺ¸°ŮŔ» şŻ°ćÇĎ´Â ¸ó˝şĹÍ ±¸Çö - 
		return;
	}

	mt_auto_lock mtAuto(&m_mtvectAttackTargetMonsterIndex);
	
	if(i_Index == GetLastMonsterIndexAttack2Me())
	{// 2009-12-11 by cmkwon, µĄąĚÁö ľî±×·Î·Î Ĺ¸°ŮŔ» şŻ°ćÇĎ´Â ¸ó˝şĹÍ ±¸Çö - 
		return;
	}

	vectorClientIndex::iterator it = find(m_mtvectAttackTargetMonsterIndex.begin(), m_mtvectAttackTargetMonsterIndex.end(), i_Index);
	if(it == m_mtvectAttackTargetMonsterIndex.end())
	{
		if(m_mtvectAttackTargetMonsterIndex.size() >= 20)
		{// Ĺ¸°Ů ŔÎµ¦˝ş´Â ĂÖ´ë 20°ł¸¸ ŔŻÁöÇŃ´Ů

			m_mtvectAttackTargetMonsterIndex.erase(m_mtvectAttackTargetMonsterIndex.begin());
		}
		m_mtvectAttackTargetMonsterIndex.push_back(i_Index);		
	}	
	SetLastMonsterIndexAttack2Me(i_Index);

// 2009-12-10 by cmkwon, TEMP 
//	g_pFieldGlobal->WriteSystemLogEX(TRUE, "[TEMP] 091210 %s inserted MonsterIndex(%d) ListCnt(%d) AttckMonIdx(%d) TargetMonIdx(%d)\r\n"
//		, GetCharacterString(GetCharacter(), string()), i_Index, m_mtvectAttackTargetMonsterIndex.size(), GetLastMonsterIndexAttack2Me(), m_nTargetMonsterIndex);
}


void CFieldIOCPSocket::DeleteAttackTargetIndexVector(ClientIndex_t i_Index)
{
	mt_auto_lock mtAuto(&m_mtvectAttackTargetMonsterIndex);
	vectorClientIndex::iterator it = find(m_mtvectAttackTargetMonsterIndex.begin(), m_mtvectAttackTargetMonsterIndex.end(), i_Index);
	if(it != m_mtvectAttackTargetMonsterIndex.end())
	{
		m_mtvectAttackTargetMonsterIndex.erase(it);
	}

	// 2009-12-11 by cmkwon, µĄąĚÁö ľî±×·Î·Î Ĺ¸°ŮŔ» şŻ°ćÇĎ´Â ¸ó˝şĹÍ ±¸Çö - 
	if(i_Index == GetLastMonsterIndexAttack2Me())
	{
		SetLastMonsterIndexAttack2Me(0);
	}
	if(i_Index == GetTargetMonsterIndex())
	{
		SetTargetMonsterIndex(0);
	}

// 2009-12-10 by cmkwon, TEMP 
//	g_pFieldGlobal->WriteSystemLogEX(TRUE, "[TEMP] 091210 %s deleted MonsterIndex(%d) ListCnt(%d) AttckMonIdx(%d) TargetMonIdx(%d)\r\n"
//		, GetCharacterString(GetCharacter(), string()), i_Index, m_mtvectAttackTargetMonsterIndex.size(), GetLastMonsterIndexAttack2Me(), m_nTargetMonsterIndex);
}


struct For_Each_DeleteMe_From_MonsterAttackedList
{
	For_Each_DeleteMe_From_MonsterAttackedList(ClientIndex_t nDelIdx, CFieldMapChannel *pFieldMapChannel):m_nDelIndex(nDelIdx), m_pFieldMapChannel(pFieldMapChannel){};
	void operator()(ClientIndex_t &index)
	{
		CFieldMonster *pMon = m_pFieldMapChannel->GetFieldMonster(index, 9);
		if(pMon)
		{
			pMon->DeleteAttackedInfowithIndex(m_nDelIndex);			
		}
	}
	CFieldMapChannel	*m_pFieldMapChannel;
	ClientIndex_t		m_nDelIndex;
};

void CFieldIOCPSocket::DeleteMeFromMonsterAttackedList(void)
{
	if(NULL == m_pCurrentFieldMapChannel){				return;}

	mt_auto_lock mtAuto(&m_mtvectAttackTargetMonsterIndex);
// 2009-12-10 by cmkwon, TEMP 
//	g_pFieldGlobal->WriteSystemLogEX(TRUE, "[TEMP] 091210 %s clear MonsterTargetList ListCnt(%d) AttckMonIdx(%d) TargetMonIdx(%d)\r\n"
//		, GetCharacterString(GetCharacter(), string()), m_mtvectAttackTargetMonsterIndex.size(), GetLastMonsterIndexAttack2Me(), m_nTargetMonsterIndex);

	if(m_mtvectAttackTargetMonsterIndex.empty())
	{
		return;
	}
	mtvectClientIndex_t		tempMtvect;
	tempMtvect.reserve(m_mtvectAttackTargetMonsterIndex.size());
	tempMtvect.insert(tempMtvect.begin()
		, m_mtvectAttackTargetMonsterIndex.begin(), m_mtvectAttackTargetMonsterIndex.end());
	m_mtvectAttackTargetMonsterIndex.clear();
	SetLastMonsterIndexAttack2Me(0);		// 2009-12-11 by cmkwon, µĄąĚÁö ľî±×·Î·Î Ĺ¸°ŮŔ» şŻ°ćÇĎ´Â ¸ó˝şĹÍ ±¸Çö - 
	SetTargetMonsterIndex(0);				// 2009-12-11 by cmkwon, µĄąĚÁö ľî±×·Î·Î Ĺ¸°ŮŔ» şŻ°ćÇĎ´Â ¸ó˝şĹÍ ±¸Çö - 
	mtAuto.auto_unlock_cancel();

	for_each(tempMtvect.begin(), tempMtvect.end()
		, For_Each_DeleteMe_From_MonsterAttackedList(m_character.ClientIndex, m_pCurrentFieldMapChannel));
	
}

BOOL CFieldIOCPSocket::SendAddDataBuffer(GBUFFER_SIZE_MAX_PACKET &i_gbuffer, EN_PACKET_PRIORITY i_enPacketPriority)
{
	return CIOCPSocket::SendAddData(i_gbuffer.GetPtr(), i_gbuffer.GetSize(), i_enPacketPriority);
}

BOOL CFieldIOCPSocket::IsTrivialMessageType(MessageType_t msgType)
{
	if (T0_FC_STRING			== HIBYTE(msgType) ||
		T0_FC_MOVE				== HIBYTE(msgType) ||
//		T0_FC_BATTLE			== HIBYTE(msgType) ||
		T0_FC_CHARACTER			== HIBYTE(msgType) ||
		T0_FC_ADMIN				== HIBYTE(msgType) ||
		T_FC_MONSTER_MOVE_OK	== msgType ||
		IS_ALIVE_MSG(msgType)
	)
	{
		return TRUE;
	}

	return FALSE;
}

#ifdef _DEBUG
// check: EVENT °ü·Ă MSG ¸ř ş¸ł»´Â µîŔÇ ą®Á¦ ŔÖŔ˝! ÁÁŔş ąćąý ĂŁľĆľß ÇÔ.
// check: SendInRangeXXX() µîżˇĽ­ casting ľřŔĚ CIOCPSocket::SendAddData()¸¦ ąŮ·Î ČŁĂâÇĎ´Â °ćżě´Â ľČ °Ą Ľö ŔÖ´Ů. 20040831, kelovon.
BOOL CFieldIOCPSocket::SendAddData(BYTE* pData, int nSize)
{
//	if (m_PeerSocketType == ST_CLIENT && COMPARE_BODYCON_BIT(m_character.BodyCondition, BODYCON_EVENT_HANDLE_MASK))
//	{
//		DBGOUT("SendAddData Failed: %s %d", GetCharacterString(&m_character, string()), m_PeerSocketType);
//		return FALSE;
//	}

	MessageType_t msgType = *(MessageType_t*)pData;

	if (m_PeerSocketType == ST_CLIENT_TYPE
		&& m_bSendMessgeTypeDBG
		&& !IsTrivialMessageType(msgType)
	)
	{
		SendString128(STRING_128_USER_NOTICE, "[F->C]%s", GetProtocolTypeString(msgType));
	}

	if (g_exchangeMsgPrintLevel != PRINTLEVEL_NO_MSG)
	{
		PrintExchangeMsg(SEND_TYPE, msgType, m_szPeerIP, m_PeerSocketType, GGetexchangeMsgPrintLevel());
	}

	return CIOCPSocket::SendAddData(pData, nSize);
}
#endif


void CFieldIOCPSocket::IncrementInsertingStoreCounts(void)
{
	this->m_dwLastTickInsertingStoreItem = timeGetTime();
	InterlockedIncrement(&this->m_nInsertingStoreItemCounts);
}

void CFieldIOCPSocket::DecrementInsertingStoreCounts(void)
{
	if(0 > InterlockedDecrement(&this->m_nInsertingStoreItemCounts))
	{
		this->m_nInsertingStoreItemCounts = 0;
	}
}


///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::InfluenceWarCheckInvasion(void)
/// \brief		
/// \author		cmkwon
/// \date		2005-12-28 ~ 2005-12-28
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::InfluenceWarCheckInvasion(void)
{
	///////////////////////////////////////////////////////////////////////////////
	// 2006-01-10 by cmkwon - ŔüĂĽ¸ĘŔ¸·Î ĂĽĹ©ÇĎ´ř°ÍŔ» °˘ ¸Ęş° ĂĽĹ©·Î ĽöÁ¤ÇÔ, ¸Ţ˝ĂÁö ŔüĽŰµµ ÇöŔç¸ĘŔ¸·Î¸¸ ŔüĽŰÇÔ


	CFieldMapChannel *pFMChann = GetCurrentFieldMapChannel();
	if(NULL == pFMChann)
	{
		return;
	}

	// 2007-05-22 by cmkwon, ŔĎąÝĽĽ·Âµµ˝Ă¸Ę(ľĆÄ«µĄąĚ¸Ę) ±¸Çö
	if(COMPARE_RACE(m_character.Race, RACE_OPERATION|RACE_GAMEMASTER)
		|| COMPARE_INFLUENCE(m_character.InfluenceType, INFLUENCE_TYPE_NORMAL))
	{// 2006-01-10 by cmkwon, °ü¸®ŔÚ, GMŔş ĂĽĹ©ÇĎÁö ľĘ´Â´Ů, // 2007-05-22 by cmkwon, ŔĎąÝĽĽ·Âµµ ĂĽĹ©ÇĎÁö ľĘ´Â´Ů
		return;
	}

	int nMapInfl = GetCurrentFieldMapChannel()->GetMapInfluenceTypeW();
	// 2007-05-22 by cmkwon, ŔĎąÝĽĽ·Âµµ˝Ă¸Ę(ľĆÄ«µĄąĚ¸Ę) ±¸Çö
	if(MAP_INFLUENCE_NEUTRALITY == nMapInfl
		|| IS_MAP_INFLUENCE_EVENT_AREA(nMapInfl)		// 2007-05-22 by cmkwon, ŔĚşĄĆ®¸Ęµµ ĂĽĹ©ÇĎÁö ľĘ´Â´Ů
// 2009-10-12 by cmkwon, ÇÁ¸®˝şÄ« Á¦°Ĺ ąćľČ Ŕűżë - CFieldIOCPSocket::InfluenceWarCheckInvasion#, 
//		|| IS_SAME_CHARACTER_8_MAP_INFLUENCE(m_character.InfluenceType, nMapInfl))
		|| CAtumSJ::IsSameCharacterInfluence8MapInfluence(m_character.InfluenceType, nMapInfl))		// 2009-10-12 by cmkwon, ÇÁ¸®˝şÄ« Á¦°Ĺ ąćľČ Ŕűżë - 
	{// Áß¸łżµżŞ ¸ĘŔĚ°ĹłŞ Äł¸Ż°ú °°Ŕş ĽĽ·Â¸ĘŔĚ´Ů.
		return;
	}

	DWORD		dwCurTick = timeGetTime();
	if(COMPARE_INFLUENCE(m_character.InfluenceType, INFLUENCE_TYPE_VCN))
	{// ąŮŔĚÁ¦´ĎŔŻ ĽĽ·ÂŔĚ ´Ů¸Ą ĽĽ·Â¸ĘżˇĽ­ ŔĚµżÁßŔĚ´Ů
		if(dwCurTick-pFMChann->m_dwLastTickANIInfluenceAttackedMsg <= TICKGAP_SEND_INVASION_MSG)
		{
			return;
		}
		pFMChann->m_dwLastTickANIInfluenceAttackedMsg = dwCurTick;
		INIT_MSG_WITH_BUFFER(MSG_FC_WAR_NOTIFY_INVASION, T_FC_WAR_NOTIFY_INVASION, pSInvasion, SendBuf);
		pSInvasion->MapChannelIndex0		= GetCurrentFieldMapChannel()->GetMapChannelIndex();
		pFMChann->SendMessageToAllInChannel(SendBuf, MSG_SIZE(MSG_FC_WAR_NOTIFY_INVASION), INFLUENCE_TYPE_ANI);

		///////////////////////////////////////////////////////////////////////////////
		// 2006-12-08 by dhjin, ÁöµµŔÚ, şÎÁöµµŔÚżˇ°Ô ŔüĽŰ
		ms_pFieldIOCP->Send2LeaderANDSubLeader(INFLUENCE_TYPE_ANI, SendBuf, MSG_SIZE(MSG_FC_WAR_NOTIFY_INVASION), pFMChann);
	}
	else if(COMPARE_INFLUENCE(m_character.InfluenceType, INFLUENCE_TYPE_ANI))
	{// ľË¸µĹĎ ĽĽ·ÂŔĚ ´Ů¸Ą ĽĽ·Â¸ĘżˇĽ­ ŔĚµżÁßŔĚ´Ů.
		if(dwCurTick-pFMChann->m_dwLastTickVCNInfluenceAttackedMsg <= TICKGAP_SEND_INVASION_MSG)
		{
			return;
		}
		pFMChann->m_dwLastTickVCNInfluenceAttackedMsg = dwCurTick;
		INIT_MSG_WITH_BUFFER(MSG_FC_WAR_NOTIFY_INVASION, T_FC_WAR_NOTIFY_INVASION, pSInvasion, SendBuf);
		pSInvasion->MapChannelIndex0		= GetCurrentFieldMapChannel()->GetMapChannelIndex();
		pFMChann->SendMessageToAllInChannel(SendBuf, MSG_SIZE(MSG_FC_WAR_NOTIFY_INVASION), INFLUENCE_TYPE_VCN);

		///////////////////////////////////////////////////////////////////////////////
		// 2006-12-08 by dhjin, ÁöµµŔÚ, şÎÁöµµŔÚżˇ°Ô ŔüĽŰ
		ms_pFieldIOCP->Send2LeaderANDSubLeader(INFLUENCE_TYPE_VCN, SendBuf, MSG_SIZE(MSG_FC_WAR_NOTIFY_INVASION), pFMChann);
	}
}


///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::InfluenceWarBonus2Killer(CFieldIOCPSocket *i_pFISockDeaded)
/// \brief		
/// \author		cmkwon
/// \date		2006-02-09 ~ 2006-02-09
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::InfluenceWarBonus2Killer(CFieldIOCPSocket *i_pFISockDeaded)
{
	this->SendString128(STRING_128_USER_NOTICE, "\\c-------------------------------\\c");
	const CHARACTER* pDeadedChar = i_pFISockDeaded->GetCharacter();
	char szTmp[1024]; *szTmp = '\0';


	if (!g_pFieldGlobal->IsArenaServer() && MAP_INFLUENCE_PVP_ALL == m_pCurrentFieldMapChannel->m_pFieldMapProject->GetMapInfluenceType()) {
		sprintf(szTmp, "\\yKilled \\gFFA Enemy \\yreceived:");
		this->SendString128(STRING_128_USER_NOTICE, szTmp);
		//give KM
		m_ItemManager.InsertItemBaseByItemNum(9900295, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);

		/////////////////deaded item info
		mt_auto_lock igLock(&m_ItemManager.m_mapItemGeneral);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\g[Killer EQ items]");
		for (auto& el : this->m_ItemManager.m_mapItemGeneral)
		{
			if (el.second->Wear == TRUE)
			{
				bool bPrefPr = false;
				bool bSufPr = false;

				RARE_ITEM_INFO* pRareItemInfoPrefix = ms_pFieldIOCP->GetRareItemInfo(el.second->PrefixCodeNum);
				RARE_ITEM_INFO* pRareItemInfoSuf = ms_pFieldIOCP->GetRareItemInfo(el.second->SuffixCodeNum);

				if (pRareItemInfoPrefix) bPrefPr = true;
				if (pRareItemInfoSuf) bSufPr = true;

				string itemKind = "";
				if (IS_PRIMARY_WEAPON(el.second->Kind))
					itemKind = "\\cStandard weapon\\c";
				else if (IS_SECONDARY_WEAPON(el.second->Kind))
					itemKind = "\\lAdvanced weapon\\l";
				else if (el.second->Kind == ITEMKIND_DEFENSE)
					itemKind = "\\yArmor\\y";
				else if (el.second->Kind == ITEMKIND_SUPPORT)
					itemKind = "\\pEngine\\p";
				else if (el.second->Kind == ITEMKIND_COMPUTER)
					itemKind = "\\tCPU\\t";
				else
					continue;

				int nNumOfEnchants = 0;
				m_mapEnchant.lock();
				vector<pair<int, string>> vecEnchantdesc;
				vecEnchantdesc.clear();
				char szTmp[1024];
				mtmapUID2EnchantVector::iterator itrEnchantList = m_mapEnchant.find(el.second->UniqueNumber);
				if (itrEnchantList != m_mapEnchant.end())
				{
					vectENCHANT& vecECH = itrEnchantList->second;
					nNumOfEnchants = vecECH.size();

					for (int i = 0; i < nNumOfEnchants; i++)
					{
						int count = 0;
						for (auto& cn : vecECH)
						{
							if (cn.EnchantItemNum == vecECH[i].EnchantItemNum)
								count++;
						}

						memset(szTmp, 0x00, 1024);
						sprintf(szTmp, "%d x %s", count, ms_pFieldIOCP->GetItemInfo(vecECH[i].EnchantItemNum)->ItemName);
						string strTm(szTmp);
						bool bAlreadyHere = false;
						for (auto& el2 : vecEnchantdesc)
						{
							if (el2.first == vecECH[i].EnchantItemNum) {
								bAlreadyHere = true;
								break;
							}
						}

						if (!bAlreadyHere)
							vecEnchantdesc.emplace_back(vecECH[i].EnchantItemNum, strTm);

					}
				}
				// unlock
				m_mapEnchant.unlock();
				if (nNumOfEnchants > 0) {
					i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\a%s: \\g%s\\g %s \\g%s\\g \\eE:%d", itemKind.c_str(), bPrefPr ? pRareItemInfoPrefix->Name : " ", el.second->ItemInfo->ItemName, bSufPr ? pRareItemInfoSuf->Name : " ", nNumOfEnchants);
					for (auto& elm : vecEnchantdesc)
					{
						i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\e   - %s", elm.second.c_str());
					}
				}
				else
					i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\a%s: \\g%s\\g %s \\g%s\\g", itemKind.c_str(), bPrefPr ? pRareItemInfoPrefix->Name : " ", el.second->ItemInfo->ItemName, bSufPr ? pRareItemInfoSuf->Name : " ");

			}
		}

		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\g[Killer stat points]");
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aAttack stat: \\y%d", this->m_character.TotalGearStat.AttackPart);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aDef stat: \\y%d", this->m_character.TotalGearStat.DefensePart);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aFuel stat: \\y%d", this->m_character.TotalGearStat.FuelPart);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aSP stat: \\y%d", this->m_character.TotalGearStat.SoulPart);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aShield stat: \\y%d", this->m_character.TotalGearStat.ShieldPart);
		i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aEva stat: \\y%d", this->m_character.TotalGearStat.DodgePart);

		igLock.auto_unlock_cancel();
//update pvp points
		// send log
		CAtumLogSender::SendLogMessagePKLOSS(i_pFISockDeaded, this->m_character.CharacterUniqueNumber);
		CAtumLogSender::SendLogMessagePKWIN(this, i_pFISockDeaded->m_character.CharacterUniqueNumber);

		// Winner
		this->m_character.PKWinPoint += 1;
		this->CheckAndUpdateStatus();
		this->SendCharacterInfo(T_FC_CHARACTER_CHANGE_PKPOINT);

		QPARAM_CHARACTER_CHANGE_PKPOINT* pQChangePKPointWinner = new QPARAM_CHARACTER_CHANGE_PKPOINT;
		pQChangePKPointWinner->CharacterUniqueNumber = this->m_character.CharacterUniqueNumber;
		pQChangePKPointWinner->Propensity = this->m_character.Propensity;
		pQChangePKPointWinner->DeathCount = this->m_character.DownSPIOnDeath;
		pQChangePKPointWinner->PKWinPoint = this->m_character.PKWinPoint;
		pQChangePKPointWinner->PKLossPoint = this->m_character.PKLossPoint;
		this->ms_pFieldIOCP->m_pAtumDBManager->MakeAndEnqueueQuery(QT_ChangePKPoint, this, this->m_character.AccountUniqueNumber, pQChangePKPointWinner);

		// Loser
		i_pFISockDeaded->m_character.PKLossPoint += 1;
		i_pFISockDeaded->CheckAndUpdateStatus();
		i_pFISockDeaded->SendCharacterInfo(T_FC_CHARACTER_CHANGE_PKPOINT);
		QPARAM_CHARACTER_CHANGE_PKPOINT* pQChangePKPointLoser = new QPARAM_CHARACTER_CHANGE_PKPOINT;
		pQChangePKPointLoser->CharacterUniqueNumber = i_pFISockDeaded->m_character.CharacterUniqueNumber;
		pQChangePKPointLoser->Propensity = i_pFISockDeaded->m_character.Propensity;
		pQChangePKPointWinner->DeathCount = i_pFISockDeaded->m_character.DownSPIOnDeath;
		pQChangePKPointLoser->PKWinPoint = i_pFISockDeaded->m_character.PKWinPoint;
		pQChangePKPointLoser->PKLossPoint = i_pFISockDeaded->m_character.PKLossPoint;
		i_pFISockDeaded->ms_pFieldIOCP->m_pAtumDBManager->MakeAndEnqueueQuery(QT_ChangePKPoint, i_pFISockDeaded, i_pFISockDeaded->m_character.AccountUniqueNumber, pQChangePKPointLoser);
	
		//fame/dead stats
		this->AddCharacterFame();
		i_pFISockDeaded->AddCharacterFame(0, 0, 1);

		return; //end of FA map
	}
	sprintf(szTmp, "\\yKilled \\g%s \\yLv. \\g%d \\yreceived:", pDeadedChar->CharacterName, pDeadedChar->Level);
	this->SendString128(STRING_128_USER_NOTICE, szTmp);
//////////////////////////kill assist - if took more than 10% of hp
	/*const auto p = std::minmax_element(i_pFISockDeaded->vec_LastAttackers.begin(), i_pFISockDeaded->vec_LastAttackers.end());
	auto min = p.first->second;
	auto max = p.second->second;*/
	bool bAssisted = false;
	CFieldIOCPSocket *TmpHealSock = NULL;
	ATUM_DATE_TIME tmNowTime(TRUE);
	auto fmaxDeadedCharHP = i_pFISockDeaded->m_character.HP + i_pFISockDeaded->m_character.DP;
	for (auto& lastA : i_pFISockDeaded->vec_LastAttackers)
	{
			//get % of dead player hp dealt
			auto fPerc = lastA.second.second/ fmaxDeadedCharHP * 100.0f;
			if (fPerc >= 10.0f)
			{
				if (!lastA.second.first || FALSE == lastA.second.first->IsValidCharacter()) {
					bAssisted = false;
				}
				else if(lastA.second.first->m_character.MapChannelIndex.IsSameMapChannelIndex(i_pFISockDeaded->m_character.MapChannelIndex)
					&& tmNowTime.GetTimeDiffTimeInSeconds(lastA.first) <= 60)
				{
					lastA.second.first->SendString128(STRING_128_USER_NOTICE, "\\g[Kill assist] \\lYou have assisted to kill \\g%s\\l dealt \\g%.2f%%\\l of his total HP", i_pFISockDeaded->m_character.CharacterName, fPerc);
				//	lastA.first->SendString128(STRING_128_USER_NOTICE, "\\lYou have assisted to kill \\g%s\\l dealt \\g%.2f%%\\l of his total HP", i_pFISockDeaded->m_character.CharacterName, fPerc);
					i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\y[\\p%s\\y] have assisted to kill you. Dealt \\p%.2f%%\\y of your total HP", lastA.second.first->m_character.CharacterName, fPerc);
					
					lastA.second.first->m_ItemManager.InsertItemBaseByItemNum(9500005, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
					CFieldGlobal::WriteSystemLogEX(FALSE, "[Inet_Robenia_Chain] Item 9500005(Data Pot Fragment) given to player %s for killing %s\r\n", lastA.second.first->m_character.CharacterName, i_pFISockDeaded->m_character.CharacterName);

					for (auto& lastHeal : lastA.second.first->vec_LastHealers)
					{
						if (!lastHeal.second.first || FALSE == lastHeal.second.first->IsValidCharacter()) {
							bAssisted = false;
						}
						else
						{//heal assisted
							if (lastHeal.second.second >= 5 && tmNowTime.GetTimeDiffTimeInSeconds(lastHeal.first) <= 60)
							{
								lastHeal.second.first->SendString128(STRING_128_USER_NOTICE, "\\g[Kill assist]\\g");
								lastHeal.second.first->SendString128(STRING_128_USER_NOTICE, "\\lYou have assisted to kill \\g%s\\l healed \\g%s\\l \\a%d\\l times", i_pFISockDeaded->m_character.CharacterName, lastA.second.first->m_character.CharacterName, lastHeal.second.second);
								i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\y[%s] have assisted to kill you. Healed %dx your killer assistant %s", lastHeal.second.first->m_character.CharacterName, lastHeal.second.second, lastA.second.first->m_character.CharacterName);
								lastA.second.first->SendString128(STRING_128_USER_NOTICE, "\\l[\\g%s\\l] have assisted you to kill \\g%s\\l - healed you \\g%d\\l times", lastHeal.second.first->m_character.CharacterName, i_pFISockDeaded->m_character.CharacterName, lastHeal.second.second);
								
								lastHeal.second.first->m_ItemManager.InsertItemBaseByItemNum(9500005, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
								CFieldGlobal::WriteSystemLogEX(FALSE, "[Inet_Robenia_Chain] Item 9500005(Data Pot Fragment) given to player %s for healing %s\r\n", lastHeal.second.first->m_character.CharacterName, i_pFISockDeaded->m_character.CharacterName);

								bAssisted = true;
								TmpHealSock = lastHeal.second.first;
								break;
							}
						}
					}
#ifdef _INET_WP_PER_KILL
					if (g_pFieldGlobal->m_nWarpointPerKill > 0)
					{
						switch (g_pFieldGlobal->m_nWPPerKillMode)
						{
							case 0:
							{
								int nWpToAdd = (int)g_pFieldGlobal->m_nWarpointPerKill * (fPerc / 100.0f);

								if (!bAssisted) {
									lastA.second.first->SetWarPoint(nWpToAdd, true);
								}
								else
								{
									lastA.second.first->SetWarPoint(nWpToAdd/2, true);
									if (TmpHealSock || TRUE == TmpHealSock->IsValidCharacter()) {
										TmpHealSock->SetWarPoint(nWpToAdd / 2, true);
									}
								}
							}
							break;
							case 1:
							{
								int nWpToAdd = (int)(((pDeadedChar->Level / 2) + g_pFieldGlobal->m_nWarpointPerKill) * g_pFieldGlobal->m_fWPPerKillMultipler) * (fPerc / 100.0f);
								if (!bAssisted) {
									lastA.second.first->SetWarPoint(nWpToAdd, true);
								}
								else
								{
									lastA.second.first->SetWarPoint(nWpToAdd / 2, true);
									if (TmpHealSock || TRUE == TmpHealSock->IsValidCharacter()) {
										TmpHealSock->SetWarPoint(nWpToAdd / 2, true);
									}
								}
							}
							break;
						}
					}
#endif
				}
			}		
	}


/////////////////deaded item info
	mt_auto_lock igLock(&m_ItemManager.m_mapItemGeneral);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\g[Killer EQ items]");
	for (auto &el : this->m_ItemManager.m_mapItemGeneral)
	{
		if (el.second->Wear == TRUE)
		{
			bool bPrefPr = false;
			bool bSufPr = false;
			
			RARE_ITEM_INFO* pRareItemInfoPrefix = ms_pFieldIOCP->GetRareItemInfo(el.second->PrefixCodeNum);
			RARE_ITEM_INFO* pRareItemInfoSuf = ms_pFieldIOCP->GetRareItemInfo(el.second->SuffixCodeNum);

			if (pRareItemInfoPrefix) bPrefPr = true;
			if (pRareItemInfoSuf) bSufPr = true;

			string itemKind = "";
			if(IS_PRIMARY_WEAPON(el.second->Kind))
				itemKind = "\\cStandard weapon\\c";
			else if (IS_SECONDARY_WEAPON(el.second->Kind))
				itemKind = "\\lAdvanced weapon\\l";
			else if (el.second->Kind == ITEMKIND_DEFENSE)
				itemKind = "\\yArmor\\y";
			else if (el.second->Kind == ITEMKIND_SUPPORT)
				itemKind = "\\pEngine\\p";
			else if (el.second->Kind == ITEMKIND_COMPUTER) 
				itemKind = "\\tCPU\\t";		
			else
				continue;

			int nNumOfEnchants = 0;
			m_mapEnchant.lock();
			vector<pair<int,string>> vecEnchantdesc;
			vecEnchantdesc.clear();
			char szTmp[1024];
			mtmapUID2EnchantVector::iterator itrEnchantList = m_mapEnchant.find(el.second->UniqueNumber);
			if (itrEnchantList != m_mapEnchant.end())
			{
				vectENCHANT& vecECH = itrEnchantList->second;
				nNumOfEnchants = vecECH.size();
							
				for (int i = 0; i < nNumOfEnchants; i++)
				{
					int count = 0;
					for (auto &cn : vecECH)
					{
						if(cn.EnchantItemNum == vecECH[i].EnchantItemNum)
							count ++;
					}
					
					memset(szTmp,0x00,1024);
					sprintf(szTmp,"%d x %s", count,ms_pFieldIOCP->GetItemInfo(vecECH[i].EnchantItemNum)->ItemName);
					string strTm(szTmp);
					bool bAlreadyHere = false;
					for (auto &el2 : vecEnchantdesc)
					{
						if (el2.first == vecECH[i].EnchantItemNum) {
							bAlreadyHere=true;
							break;
						}
					}

					if(!bAlreadyHere)
						vecEnchantdesc.emplace_back(vecECH[i].EnchantItemNum, strTm);

				}
			}
			// unlock
			m_mapEnchant.unlock();
			if (nNumOfEnchants > 0) {
				i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\a%s: \\g%s\\g %s \\g%s\\g \\eE:%d", itemKind.c_str(), bPrefPr ? pRareItemInfoPrefix->Name : " ", el.second->ItemInfo->ItemName, bSufPr ? pRareItemInfoSuf->Name : " ", nNumOfEnchants);
				for (auto &elm : vecEnchantdesc)
				{
					i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE,"\\e   - %s",elm.second.c_str());
				}
			}
			else
				i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\a%s: \\g%s\\g %s \\g%s\\g", itemKind.c_str(), bPrefPr ? pRareItemInfoPrefix->Name : " ", el.second->ItemInfo->ItemName, bSufPr ? pRareItemInfoSuf->Name : " ");
			
		}
	}

	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\g[Killer stat points]");
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aAttack stat: \\y%d", this->m_character.TotalGearStat.AttackPart);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aDef stat: \\y%d", this->m_character.TotalGearStat.DefensePart);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aFuel stat: \\y%d", this->m_character.TotalGearStat.FuelPart);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aSP stat: \\y%d", this->m_character.TotalGearStat.SoulPart);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aShield stat: \\y%d", this->m_character.TotalGearStat.ShieldPart);
	i_pFISockDeaded->SendString128(STRING_128_USER_NOTICE, "\\aEva stat: \\y%d", this->m_character.TotalGearStat.DodgePart);

	igLock.auto_unlock_cancel();


//////////////////lololo
#ifdef _INET_WP_PER_KILL
	if (g_pFieldGlobal->m_nWarpointPerKill > 0)
	{
		switch (g_pFieldGlobal->m_nWPPerKillMode)
		{
		case 0:
		{
			this->SetWarPoint(g_pFieldGlobal->m_nWarpointPerKill, true);
		}
		break;
		case 1:
		{
			int nWpInsert = ((pDeadedChar->Level / 2) + g_pFieldGlobal->m_nWarpointPerKill) * g_pFieldGlobal->m_fWPPerKillMultipler;
			if(IS_MGEAR(i_pFISockDeaded->m_character.UnitKind) || IS_MGEAR(this->m_character.UnitKind))
				this->SetWarPoint(nWpInsert * 1.25f,true);
			else
				this->SetWarPoint(nWpInsert,true);
		}
		break;
		}
	}
#endif

//EXP PER KILL - 30-03-2021 by Inet
	if(g_pFieldGlobal->m_nEXPPerKillBaseAmount > 0 && pDeadedChar->Level >= g_pFieldGlobal->m_nEXPPerKillMinDeadLv)
	{
		//mylevel - hislevel
		auto f_LevelDiffBonus = static_cast<Experience_t>(m_character.Level) - static_cast<Experience_t>(pDeadedChar->Level);
		if(f_LevelDiffBonus > 0 || f_LevelDiffBonus < -10)//if dead character was lower level or difference is higher than 10 levels
			f_LevelDiffBonus = 0;
		else
			f_LevelDiffBonus = static_cast<Experience_t>(g_pFieldGlobal->m_nEXPPerKillBaseAmount) * (f_LevelDiffBonus / -10); //max 0.9 so 90% of base exp
		
		//his fame - my fame
		auto f_FameDiffBonus = static_cast<Experience_t>(pDeadedChar->Propensity) - static_cast<Experience_t>(m_character.Propensity);
		if(f_FameDiffBonus < 1000) {
			f_FameDiffBonus = 0;
		}
		else {
			if (f_FameDiffBonus / 10000 > 1)
				f_FameDiffBonus = static_cast<Experience_t>(g_pFieldGlobal->m_nEXPPerKillBaseAmount);
			else
				f_FameDiffBonus = static_cast<Experience_t>(g_pFieldGlobal->m_nEXPPerKillBaseAmount) * (f_FameDiffBonus / 10000);
		}

		//SP/MS/AB bonus
		Experience_t f_SPMSABBonus{ 0 };
		if (ms_pFieldIOCP->m_InflWarManager.IsDoingInfluenceWar() == TRUE)
			f_SPMSABBonus = static_cast<Experience_t>(g_pFieldGlobal->m_nEXPPerKillBaseAmount) * (static_cast<Experience_t>(g_pFieldGlobal->m_nInflWarPercentAdd) / 100);
		
		auto f_ExpToAdd = static_cast<Experience_t>(g_pFieldGlobal->m_nEXPPerKillBaseAmount) + f_LevelDiffBonus + f_FameDiffBonus + f_SPMSABBonus;
		
		sprintf(szTmp, "\\yEXP Base: \\g%d", g_pFieldGlobal->m_nEXPPerKillBaseAmount);
		this->SendString128(STRING_128_USER_NOTICE, szTmp);
		if (f_LevelDiffBonus > 0) {
			sprintf(szTmp, "\\yLevel difference bonus: \\g%f", f_LevelDiffBonus);
			this->SendString128(STRING_128_USER_NOTICE, szTmp);
		}
		if (f_FameDiffBonus > 0) {
			sprintf(szTmp, "\\yFame difference bonus: \\g%f", f_FameDiffBonus);
			this->SendString128(STRING_128_USER_NOTICE, szTmp);
		}
		if (f_SPMSABBonus > 0) {
			sprintf(szTmp, "\\yInfluence War bonus: \\g%f", f_SPMSABBonus);
			this->SendString128(STRING_128_USER_NOTICE, szTmp);
		}
		sprintf(szTmp, "\\yTotal base exp: \\g%f", f_ExpToAdd);
		this->SendString128(STRING_128_USER_NOTICE, szTmp);

		if (IS_MGEAR(i_pFISockDeaded->m_character.UnitKind) || IS_MGEAR(this->m_character.UnitKind))
			f_ExpToAdd *= 1.25f;

		this->ChangeExperience(f_ExpToAdd, TRUE, TRUE, TRUE);		
	}
//END EXP PER KILL
	///////////////////////////////////////////////////////////////////////////////	
	// 2006-02-09 by cmkwon, Ĺł¸¶Ĺ© łÖľî ÁÖ±â
	ITEM *pKillMarkItem = i_pFISockDeaded->GetGiveKillMarkItemPtr2Killer();
	if(pKillMarkItem)
	{

		if(pDeadedChar->Level >= 72) //quest is started
		{
			int nQuestType = 0;
			mt_auto_lock mtAuto(&m_mapQuest);
			mtmapQuestIndex2FieldCharacterQuest::iterator itrQuest(m_mapQuest.begin());
			for(; itrQuest != m_mapQuest.end(); itrQuest++)
			{
				CFieldCharacterQuest *pFCharQuest = &itrQuest->second;
				if (pFCharQuest->QuestState == QUEST_STATE_IN_PROGRESS)
				{
					CQuest *pQuestInfo = pFCharQuest->GetQuestInfo();
					if(pQuestInfo->IsCityWar)
					{
						nQuestType = pQuestInfo->QuestIndex;
					}
				}
			}
			
			if(nQuestType != 0 && ms_pFieldIOCP->m_InflWarManager.CheckSummonOnlyStrategyPoint() && ms_pFieldIOCP->m_InflWarManager.CheckSPSummonMapIndex(this->m_character.MapChannelIndex.MapIndex) && nQuestType < 3013){ //is SP and player is on sp map
				m_ItemManager.InsertItemBaseByItemNum(9900293, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
				CFieldGlobal::WriteSystemLogEX(FALSE,"[Inet_Daily_Quest] Item 9900293(SP fight killmark) given to player %s for killing %s on SP map %d \r\n", this->m_character.CharacterName, pDeadedChar->CharacterName,this->m_character.MapChannelIndex.MapIndex);
			}
			else if(nQuestType != 0 && !ms_pFieldIOCP->m_InflWarManager.CheckSummonOnlyStrategyPoint() && nQuestType > 3012){ //no sp just casual fight
				m_ItemManager.InsertItemBaseByItemNum(9900294, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
				CFieldGlobal::WriteSystemLogEX(FALSE,"[Inet_Daily_Quest] Item 9900294(Free fight killmark) given to player %s for killing %s \r\n", this->m_character.CharacterName, pDeadedChar->CharacterName);
			}

		}
		
		BOOL bInserted = m_ItemManager.InsertItemBaseByItemNum(pKillMarkItem->ItemNum, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
		
		this->m_ItemManager.InsertItemBaseByItemNum(9500005, 1, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
		CFieldGlobal::WriteSystemLogEX(FALSE, "[Inet_Robenia_Chain] Item 9500005(Data Pot Fragment) given to player %s for healing %s\r\n", this->m_character.CharacterName, i_pFISockDeaded->m_character.CharacterName);

		if(FALSE == bInserted)
		{
			// 2009-11-02 by cmkwon, Äł˝¬(ŔÎşĄ/Ă˘°í Č®Ŕĺ) ľĆŔĚĹŰ Ăß°ˇ ±¸Çö - 
			SendErrorMessage(T_FIELD_IOCP, ERR_PROTOCOL_INVENTORY_FULL_ITEM, m_ItemManager.GetMaxInventoryCount(), m_ItemManager.GetInventoryItemCounts());
		}
	}

	// 2006-02-09 by cmkwon, ¸íĽşÄˇ ş¸łĘ˝ş
	this->AddCharacterFame();
	i_pFISockDeaded->AddCharacterFame(0,0,1);

	
	CHARACTER2ITEMLIST *pChar2ItemList = ms_pFieldIOCP->FindCharacter2Item(pDeadedChar->InfluenceType, pDeadedChar->UnitKind);
	if(NULL == pChar2ItemList)
	{
		return;
	}

	float fPlusDropItem		= i_pFISockDeaded->GetPlusRateDropItem() - 1.0f;
	for(int i=0; i < pChar2ItemList->vectCharacter2Item.size(); i++)
	{
		CHARACTER2ITEM *pChar2Item = &pChar2ItemList->vectCharacter2Item[i];
		ITEM	*pDropItem	= ms_pFieldIOCP->GetItemInfo(pChar2Item->ItemNumber);
		if (pDropItem == NULL
			|| FALSE == COMPARE_BIT_FLAG(pDropItem->ItemAttribute, ITEM_ATTR_QUEST_ITEM)
			|| FALSE == COMPARE_BIT_FLAG(pDropItem->ItemAttribute, ITEM_ATTR_KILL_MARK_ITEM)
			|| 0 >= pChar2Item->QuestIndex)
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] Character DropItem Error1, Influence(%2d) UnitKind(%8d) ItemNum(%8d) QuestIndex(%4d)\r\n"
				, pDeadedChar->InfluenceType, pDeadedChar->UnitKind, pChar2Item->ItemNumber, pChar2Item->QuestIndex);
			continue;
		}

		if(FALSE == IS_IN_RANGE(pDropItem->ReqMinLevel, pDeadedChar->Level, pDropItem->ReqMaxLevel))
		{
			continue;
		}
	
		mt_auto_lock mtA(&this->m_mapQuest);
		CFieldCharacterQuest *pFCharQuest = this->GetCharacterQuestInProgress();
		if(NULL == pFCharQuest
			|| pChar2Item->QuestIndex != pFCharQuest->QuestIndex)
		{// 2006-03-02 by cmkwon, ÁřÇŕÁß Äů˝şĆ®°ˇ ľř°ĹłŞ Äů˝şĆ®°ˇ ´Ů¸Ł¸é
			continue;
		}

		int pValue = RAND1000K();
		if (pChar2Item->Probability < pValue - (Prob1000K_t)(pChar2Item->Probability*fPlusDropItem))
		{// »ýĽş ˝ÇĆĐ
			continue;
		}
	
		if(pChar2Item->MinCount < 0
			|| pChar2Item->MaxCount < 0
			|| pChar2Item->MaxCount < pChar2Item->MinCount)
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] Character DropItem Error2, Influence(%2d) UnitKind(%8d) ItemNum(%8d) MinCount(%4d) MaxCount(%8d)\r\n"
				, pDeadedChar->InfluenceType, pDeadedChar->UnitKind, pChar2Item->ItemNumber, pChar2Item->MinCount, pChar2Item->MaxCount);
			continue;
		}

		INT nAmount = RANDI(pChar2Item->MinCount, pChar2Item->MaxCount);
		if(0 >= nAmount)
		{
			continue;
		}
		BOOL bInserted = m_ItemManager.InsertItemBaseByItemNum(pDropItem->ItemNum, nAmount, IUT_INFLUENCEWAR_KILLER_BONUS, TRUE);
		if(FALSE == bInserted)
		{
			// 2009-11-02 by cmkwon, Äł˝¬(ŔÎşĄ/Ă˘°í Č®Ŕĺ) ľĆŔĚĹŰ Ăß°ˇ ±¸Çö - 
			SendErrorMessage(T_FIELD_IOCP, ERR_PROTOCOL_INVENTORY_FULL_ITEM, m_ItemManager.GetMaxInventoryCount(), m_ItemManager.GetInventoryItemCounts());
			break;
		}
	}
	this->SendString128(STRING_128_USER_NOTICE, "\\y-------------------------------\\y");
}


