///////////////////////////////////////////////////////////////////////////////
/// \fn			BOOL CFieldIOCPSocket::APPopAttackParameter(SATTACK_PARAMETER *o_pAttParam, UID16_t i_WeaponIndex)
/// \brief		
/// \author		cmkwon
/// \date		2007-06-08 ~ 2007-06-08
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::APPopAttackParameter(SATTACK_PARAMETER *o_pAttParam, UID16_t i_WeaponIndex)
{
	mt_auto_lock mtA(&m_mtvectSAttackParameterList);

	DWORD dwCurTick = timeGetTime();
	mtvectSATTACK_PARAMETER::iterator itr(m_mtvectSAttackParameterList.begin());
	while(itr != m_mtvectSAttackParameterList.end())
	{
		// start 2011-06-04 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ÁÖĆ÷żë ±ä ˝Ă°Ł 2Çü ĹşµÎ ą«±â
		DWORD dwLifeTime = TICKGAP_WARHEAD_LIFETIME;	// 2011-06-04 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ÁÖĆ÷żë ±ä ˝Ă°Ł 2Çü ĹşµÎ ą«±â

		if( itr->pWeaponItemInfo->Kind == ITEMKIND_FOR_MON_MAIN_ARMAMENT  )
		{
			dwLifeTime = TICKGAP_WARHEAD_LIFETIME_LONG;;
		}
		// end 2011-06-04 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ÁÖĆ÷żë ±ä ˝Ă°Ł 2Çü ĹşµÎ ą«±â				

		if(dwCurTick - itr->dwShotTick > dwLifeTime)		// 2011-06-04 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ÁÖĆ÷żë ±ä ˝Ă°Ł 2Çü ĹşµÎ ą«±â - Ŕűżë ĽöÁ¤
		{
			itr = m_mtvectSAttackParameterList.erase(itr);
			continue;
		}
		else if(itr->WeaponIndex == i_WeaponIndex)
		{
			*o_pAttParam = *itr;
			////////////////////////////////////////////////////////////////////////////////
			// 2009-09-09 ~ 2010 by dhjin, ŔÎÇÇ´ĎĆĽ - 
			if(g_pFieldGlobal->IsArenaServer()
				// start 2011-04-08 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ˝Ăł×¸¶ ´Ü°čş° ±â´É ±¸Çö
				// ±âÁ¸
				//&& INFINITY_STATE_PLAYING == this->m_InfinityPlayingInfo.InfinityState) {
				// ĽöÁ¤
				&& TRUE == IS_INFINITY_STATE_PLAYING(this->m_InfinityPlayingInfo.InfinityState) )	{
				// end 2011-04-08 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ˝Ăł×¸¶ ´Ü°čş° ±â´É ±¸Çö
				
				// ľĆ·ąłŞ Ľ­ąöżˇĽ­ ŔÎÇÇ´ĎĆĽ ÁßŔĚ¶ó¸é ±âş»ą«±â ĂÖĽŇ °ř°Ý·Â ş¸Á¤
				if(o_pAttParam->fAttack < this->m_InfinityPlayingInfo.RevisionAdvancedWeapon) {
					o_pAttParam->fAttack = this->m_InfinityPlayingInfo.RevisionAdvancedWeapon;
				}
				if(o_pAttParam->fMaxAttack < this->m_InfinityPlayingInfo.RevisionAdvancedWeapon) {
					o_pAttParam->fMaxAttack = this->m_InfinityPlayingInfo.RevisionAdvancedWeapon;
				}
			}
			itr = m_mtvectSAttackParameterList.erase(itr);
			return TRUE;
		}

		itr++;
	}
	return FALSE;
}


///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::APCalcAttckParameter(SATTACK_PARAMETER *o_pAttParam, ITEM *i_pWeaponItemInfo, UID16_t i_WeaponIndex)
/// \brief		
/// \author		cmkwon
/// \date		2007-06-08 ~ 2007-06-08
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::APCalcAttckParameter(SATTACK_PARAMETER* o_pAttParam, ITEM* i_pWeaponItemInfo, UID16_t i_WeaponIndex, enumAttackToTarget eAttackToTarget, float i_PvPBuffPercent)	// 2013-08-01 by jhseol, żŞŔüŔÇ ąöÇÁ ¸®´şľó - i_PvPBuffPercent Ăß°ˇ	// 2013-05-09 by hskim, ĽĽ·Â Ć÷ŔÎĆ® °łĽ±
{
	BOOL			bIsPrimaryAttack	= FALSE;
	CParamFactor	*pAttParamFactor	= this->GetParamFactor();
	CHARACTER		*pCharacter			= &this->m_character;
	Stat_t			statAttackPart		= pCharacter->TotalGearStat.AttackPart; 
	if(IS_PRIMARY_WEAPON(i_pWeaponItemInfo->Kind))
	{
		o_pAttParam->dwShotTick				= 0;
		bIsPrimaryAttack					= TRUE;
	}
	else
	{// 2007-06-08 by cmkwon, 2Çü ĹşµÎ¸¸ Ăł¸®
		o_pAttParam->dwShotTick				= timeGetTime();
		bIsPrimaryAttack					= FALSE;
	}
	o_pAttParam->WeaponIndex = i_WeaponIndex;
	o_pAttParam->pWeaponItemInfo = i_pWeaponItemInfo;
	o_pAttParam->fAttackProbability = CAtumSJ::GetAttackProbabilityC(i_pWeaponItemInfo, pAttParamFactor, bIsPrimaryAttack, statAttackPart, pCharacter->Level);	// 2013-08-01 by jhseol, żŞŔüŔÇ ąöÇÁ ¸®´şľó - i_PvPBuffPercent Ăß°ˇ	// 2013-05-09 by hskim, ĽĽ·Â Ć÷ŔÎĆ® °łĽ± - // 2010-02-19 by cmkwon, 100ŔĚÇĎ ·ąş§ ĂÖ´ë˝şĹČ ĽöÄˇ ąö±× ĽöÁ¤ - ŔÎŔÚĂß°ˇ(, BYTE i_byLevel)
	o_pAttParam->fPierceAttackProbability = CAtumSJ::GetAttackC_PierceAttackProbability(statAttackPart, i_pWeaponItemInfo, pAttParamFactor, bIsPrimaryAttack, pCharacter->Level);	// 2013-08-01 by jhseol, żŞŔüŔÇ ąöÇÁ ¸®´şľó - i_PvPBuffPercent Ăß°ˇ	// 2013-05-09 by hskim, ĽĽ·Â Ć÷ŔÎĆ® °łĽ± - // 2010-02-19 by cmkwon, 100ŔĚÇĎ ·ąş§ ĂÖ´ë˝şĹČ ĽöÄˇ ąö±× ĽöÁ¤ - ŔÎŔÚĂß°ˇ(, BYTE i_byLevel)// 2008-09-22 by dhjin, ˝Ĺ±Ô ŔÎĂľĆ®
	bool bBreak = false;
	bool bForbidIncreasePvEFactor = false;
	if (eAttackToTarget == C2M)
	{

		CFieldMonster* pMonster = m_pCurrentFieldMapChannel->GetFieldMonster(o_pAttParam->TargetIndex, 3);
		if (NULL == pMonster || pMonster->m_enMonsterState == MS_NULL)
		{
			bBreak = true;
		}
		else if (NULL == pMonster->MonsterInfoPtr)
		{
			g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] APCalcAttckParameter::MONSTER_CLIENT_INDEX_START_NUM");
			bBreak = true;
		}
		if (!bBreak) {
			MONSTER_INFO* pMonInfo = pMonster->MonsterInfoPtr;
			if (NULL == pMonInfo)
			{
				g_pFieldGlobal->WriteSystemLogEX(TRUE, "[ERROR] APCalcAttckParameter::MONSTER_CLIENT_INDEX_START_NUM 2");
				bBreak=true;
			}

			if(IS_STRATEGYPOINT_MONSTER(pMonInfo->Belligerence) ||  IS_MOTHERSHIPWAR_MONSTER(pMonInfo->Belligerence) ||IS_OUTPOST_MONSTER(pMonInfo->Belligerence))
				bForbidIncreasePvEFactor = true;
		}
	}

	if(bForbidIncreasePvEFactor && !bBreak)
		i_PvPBuffPercent = 2.0f;

	o_pAttParam->fAttack = CAtumSJ::GetAttackC(pCharacter, i_pWeaponItemInfo, pAttParamFactor, bIsPrimaryAttack, eAttackToTarget, i_PvPBuffPercent);	// 2013-08-01 by jhseol, żŞŔüŔÇ ąöÇÁ ¸®´şľó - i_PvPBuffPercent Ăß°ˇ		// 2013-05-09 by hskim, ĽĽ·Â Ć÷ŔÎĆ® °łĽ±
	o_pAttParam->fMaxAttack = CAtumSJ::GetMaxAttackC(pCharacter, i_pWeaponItemInfo, pAttParamFactor, bIsPrimaryAttack, eAttackToTarget, i_PvPBuffPercent);	// 2013-08-01 by jhseol, żŞŔüŔÇ ąöÇÁ ¸®´şľó - i_PvPBuffPercent Ăß°ˇ	// 2013-05-09 by hskim, ĽĽ·Â Ć÷ŔÎĆ® °łĽ±

	////////////////////////////////////////////////////////////////////////////////
	// 2009-09-09 ~ 2010 by dhjin, ŔÎÇÇ´ĎĆĽ - 
	if(g_pFieldGlobal->IsArenaServer()

		// start 2011-04-08 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ˝Ăł×¸¶ ´Ü°čş° ±â´É ±¸Çö
		// ±âÁ¸
		//&& INFINITY_STATE_PLAYING == this->m_InfinityPlayingInfo.InfinityState) {

		// ĽöÁ¤
		&& TRUE == IS_INFINITY_STATE_PLAYING(this->m_InfinityPlayingInfo.InfinityState) ) {
		// end 2011-04-08 by hskim, ŔÎÇÇ´ĎĆĽ 3Â÷ - ˝Ăł×¸¶ ´Ü°čş° ±â´É ±¸Çö
		
		// ľĆ·ąłŞ Ľ­ąöżˇĽ­ ŔÎÇÇ´ĎĆĽ ÁßŔĚ¶ó¸é ±âş»ą«±â ĂÖĽŇ °ř°Ý·Â ş¸Á¤
		if(o_pAttParam->fAttack < this->m_InfinityPlayingInfo.RevisionStandardWeapon) {
			o_pAttParam->fAttack = this->m_InfinityPlayingInfo.RevisionStandardWeapon;
		}
		if(o_pAttParam->fMaxAttack < this->m_InfinityPlayingInfo.RevisionStandardWeapon) {
			o_pAttParam->fMaxAttack = this->m_InfinityPlayingInfo.RevisionStandardWeapon;
		}
	}

	m_CurrentAttackItemNum	= i_pWeaponItemInfo->ItemNum;					// 2009-09-09 ~ 2010 by dhjin, ŔÎÇÇ´ĎĆĽ - ŔÎÇÇ °ÔŔÓ·Î±× Ăß°ˇ
}

///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::OnDoMinutelyWorkByTimerManager(void)
/// \brief		
/// \author		cmkwon
/// \date		2007-06-13 ~ 2007-06-13
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::OnDoMinutelyWorkByTimerManager(void)
{
	int nLangTy = g_pFieldGlobal->GetLanguageType();

	///////////////////////////////////////////////////////////////////////////////
	// 2007-06-13 by cmkwon, żą´ç 7żů PCąć ÇÁ·Î¸đĽÇ(ÄáŔĚşĄĆ® ±¸Çö) - ÄáľĆŔĚĹŰÁö±Ţ
	if(LANGUAGE_TYPE_KOREAN == nLangTy
		&& this->m_bIsPCBangClient)
	{
		int nCurCnts = this->GetPCBangTotalPlayTimeInSeconds()/TERM_30MINUTES_BY_SECOND;		// 2007-06-28 by cmkwon, żą´ç 7żů PCąć ÄáŔĚşĄĆ® Áö±Ţ ˝Ă°Ł ĽöÁ¤ - 1˝Ă°ŁżˇĽ­ 30şĐŔ¸·Î ĽöÁ¤
		if(nCurCnts > this->m_nInsertPCBangEventItemLastCounts)
		{// Äá ŔĚşĄĆ® ľĆŔĚĹŰ Áö±Ţ

			this->m_nInsertPCBangEventItemLastCounts = nCurCnts;		// 2007-06-28 by cmkwon, żą´ç 7żů PCąć ÄáŔĚşĄĆ® Áö±Ţ ˝Ă°Ł ĽöÁ¤

			// 2007-06-19 by cmkwon, ÄáľĆŔĚĹŰŔ¸·Î şŻ°ć, 
// 2007-10-09 by dhjin, Äá ŔĚşĄĆ® Áľ·á  2007-06-19 by cmkwon, 7żů5ŔĎ Á¤±â Áˇ°Ë¶§ ľ÷µĄŔĚĆ®żąÁ¤
//			m_ItemManager.InsertItemBaseByItemNum(7004560, 1, IUT_GIVEEVENTITEM);
		}
	}

	///////////////////////////////////////////////////////////////////////////////
	// 2007-06-28 by cmkwon, Áß±ą ąć˝ÉĂë°ü·Ă(°ÔŔÓ ˝Ă°Ł ľË¸˛ ±¸Çö) - ąĚĽşłâ¸¸ ĂĽĹ©
	if(LANGUAGE_TYPE_CHINESE == nLangTy
		&& FALSE == this->IsAdultsUser())
	{
		DWORD dwCurTick = timeGetTime();
		if(TERM_10MINUTES_BY_MILLISECOND < dwCurTick-m_dwSendPlayTimeInfoLastTick)
		{
			int nGameContinueMinutesOfToday = this->GetCurGameContinueTimeInSecondOfToday()/60;
			if(30 > nGameContinueMinutesOfToday)
			{// 30şĐąĚ¸¸ - ľĆą«·± Ăł¸® ľřŔ˝
			}
			else if(TERM_GAME_PLAYTIME_LIMIT_FIRST_SEC/60+1 >= nGameContinueMinutesOfToday)
			{// 181şĐ ŔĚÇĎ
				
				// 1˝Ă°Łżˇ 1ąřľż °ć°í - 1:00, 2:00, 3:00
				if(TERM_GAME_PLAYTIME_LIMIT_FIRST_SEC/60 <= nGameContinueMinutesOfToday)
				{
					m_dwSendPlayTimeInfoLastTick		= dwCurTick;
					this->SendString128(STRING_128_USER_NOTICE, STRMSG_070628_0001, nGameContinueMinutesOfToday/60);
				}
				else if(1 >= nGameContinueMinutesOfToday%60)
				{
					m_dwSendPlayTimeInfoLastTick		= dwCurTick;
					this->SendString128(STRING_128_USER_NOTICE, STRMSG_070628_0000, nGameContinueMinutesOfToday/60);
				}
			}
			else if(TERM_GAME_PLAYTIME_LIMIT_LAST_SEC/60 > nGameContinueMinutesOfToday)
			{// 300şĐ ąĚ¸¸
				
				// 30şĐżˇ 1ąřľż °ć°í - 3:30, 4:00, 4:30
				if(1 >= nGameContinueMinutesOfToday%30)
				{
					m_dwSendPlayTimeInfoLastTick		= dwCurTick;
					this->SendString128(STRING_128_USER_NOTICE, STRMSG_070628_0002);
				}
			}
			else
			{// 300şĐ ŔĚ»ó

				// 15şĐżˇ 1ąřľż °ć°í - 5:00, 5:15, 5:30, 5:45, ...
				if(1 >= nGameContinueMinutesOfToday%15)
				{
					m_dwSendPlayTimeInfoLastTick		= dwCurTick;
					this->SendString128(STRING_128_USER_NOTICE, STRMSG_070628_0003);
				}
			}
		}
	}

	// 2007-12-06 by cmkwon, ˝Ă°ŁÁ¦ÇŃ Äů˝şĆ® Ľ­ąöżˇĽ­ ˝Ă°Ł ĂĽĹ©ÇĎ°Ô ĽöÁ¤ -
	this->CheckSuccessProgressQuestByTimeLimited();

	this->RunRanksBuff(true); //run(check) only nation buff

	ATUM_DATE_TIME tmNow(TRUE);
	int nDiffInMins = tmNow.GetTimeDiffTimeInMinutes(this->sLastAntiCheatSend);
	if (nDiffInMins >= 3) {
		CAtumLogSender::SendLogMessageMemoryHack(this, 0, 0, 0, 40000, nDiffInMins, nDiffInMins, nDiffInMins);
		CFieldGlobal::WriteSystemLogEX(FALSE, "[Inetpub Anticheat 2.0] Heartbeat fail!!! Player [ Acc: %s Char: %s IP: %s ] - Diff in minutes:%d, kicked!\r\n",
			this->m_character.AccountName, this->m_character.CharacterName, this->GetPeerIP(), nDiffInMins);

		this->Close(0x002, FALSE, 3000);
	}

}

///////////////////////////////////////////////////////////////////////////////
/// \fn			void CFieldIOCPSocket::WPAddWarPoint(INT i_nAddWarPoint, INT i_bEventBonus, BOOL i_bSend2Client/*=TRUE*/, BYTE i_byWPUpdateTy/*=WPUT_GENERAL*/)
/// \brief		// 2007-06-14 by cmkwon, ĽĽ·ÂŔü ş¸»ó ĽöÁ¤ -
///				// 2009-01-22 by cmkwon, ŔüŔď °ü·Ă °ÔŔÓ ·Î±× ĽöÁ¤ - CFieldIOCPSocket::WPAddWarPoint()żˇ ŔÎŔÚ(, BYTE i_byWPUpdateTy=WPUT_GENERAL) Ăß°ˇ
/// \author		cmkwon
/// \date		2007-06-14 ~ 2007-06-14
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
void CFieldIOCPSocket::WPAddWarPoint(INT i_nAddWarPoint, INT i_bEventBonus, BOOL i_bSend2Client/*=TRUE*/, BYTE i_byWPUpdateTy/*=WPUT_GENERAL*/)
{

	//////////////////////////////////////////////////////////////////////////
	// 2007-09-14 by dhjin, WarPoint °Ş °č»ę ÇÔĽö Ăß°ˇ
	if (WPUT_MARKET != i_byWPUpdateTy)
	{
		i_nAddWarPoint = this->CalcWarPoint(i_nAddWarPoint, i_bEventBonus);
	}

	this->m_character.WarPoint				+= i_nAddWarPoint;
	if (WPUT_MARKET != i_byWPUpdateTy)
	{
		this->m_character.CumulativeWarPoint += i_nAddWarPoint;
	}
	// 2009-01-22 by cmkwon, ŔüŔď °ü·Ă °ÔŔÓ ·Î±× ĽöÁ¤ - CAtumLogSender::SendLogMessageGetWarPoint()żˇ ŔÎŔÚ(, BYTE i_byWPUpdateTy) Ăß°ˇ
	CAtumLogSender::SendLogMessageGetWarPoint(this, i_nAddWarPoint, this->m_character.WarPoint, this->m_character.CumulativeWarPoint, i_byWPUpdateTy);
	// 2007-05-16 by dhjin, DBżˇ ľ÷µĄŔĚĆ®
	QPARAM_UPDATE_WARPOINT *pQparam = new QPARAM_UPDATE_WARPOINT;
	pQparam->CharacterUID		= this->m_character.CharacterUniqueNumber;
	pQparam->AccountUID			= this->m_character.AccountUniqueNumber;
	pQparam->TotalWarPoint		= this->m_character.WarPoint;
	pQparam->CumulativeWarPoint	= this->m_character.CumulativeWarPoint;
	ms_pFieldIOCP->m_pAtumDBManager->MakeAndEnqueueQuery(QT_UpdateWarPoint, this, this->m_character.AccountUniqueNumber, pQparam);

	if(i_bSend2Client)
	{
		// 2007-05-16 by dhjin, Ĺ¬¶óŔĚľđĆ®żˇ°Ô ŔüĽŰ
		INIT_MSG_WITH_BUFFER(MSG_FC_CHARACTER_PAY_WARPOINT, T_FC_CHARACTER_PAY_WARPOINT, pMsg, SendBuf);
		pMsg->WarPoint				= i_nAddWarPoint;
		pMsg->TotalWarPoint			= this->m_character.WarPoint;
		pMsg->CumulativeWarPoint	= this->m_character.CumulativeWarPoint;
		pMsg->UseItemFlag			= FALSE;		// 2010-08-27 by shcho&&jskim, WARPOINT Áő°ˇ ľĆŔĚĹŰ ±¸Çö - ľĆŔĚĹŰ »çżë ±¸şĐŔÚ
		this->SendAddData(SendBuf, MSG_SIZE(MSG_FC_CHARACTER_PAY_WARPOINT));
	}

}

void CFieldIOCPSocket::CREDITSAdd(INT i_nAddCredits, INT i_bEventBonus, BOOL i_bSend2Client/*=TRUE*/, BYTE i_byWPUpdateTy/*=WPUT_GENERAL*/)
{
	CODBCStatement odbcStmt;
	BOOL bRet = odbcStmt.Init(g_pGlobalGameServer->GetDBServerIP(), g_pGlobalGameServer->GetDBServerPort(), g_pGlobalGameServer->GetDBServerDatabaseName(), (LPCSTR)g_pGlobalGameServer->GetODBCUID(), (LPCSTR)g_pGlobalGameServer->GetODBCPASSWORD(), g_pGlobalGameServer->GetMainWndHandle());

	if (!bRet)
	{
		g_pGlobal->WriteSystemLogEX(TRUE, "[DB Error] _INET_CREDITS_TO_SOCK fail to connect DBServer(CFieldIOCP::IOCPInit_2) !! %s,%d %s %s %s\r\n"
			, g_pGlobalGameServer->GetDBServerIP(), g_pGlobalGameServer->GetDBServerPort(), g_pGlobalGameServer->GetDBServerDatabaseName(), (CHAR*)g_pGlobalGameServer->GetODBCUID(), (CHAR*)g_pGlobalGameServer->GetODBCPASSWORD());
		return;
	}
	char szSQLQuery[256];
	wsprintf(szSQLQuery, "USE atum2_db_account UPDATE dbo.td_Account SET CashPoint = CashPoint + %d WHERE AccountName = '%s'", i_nAddCredits, this->GetCharacter()->AccountName);
	bRet = odbcStmt.ExecuteQuery((LPCSTR)szSQLQuery);
	odbcStmt.FreeStatement();

	if (!bRet)
	{
		g_pGlobal->WriteSystemLogEX(TRUE, "[DB Error] _INET_CREDITS_TO_SOCK failed to add credits to player (%s) bRet(%d)\r\n", this->GetCharacter()->AccountName, 0);
	}
	else
	{
		//log add
		char szSQLQueryLog[256];
		wsprintf(szSQLQueryLog, "USE atum2_db_1 EXEC atum_log_insert_credits_auto '%s', %d", this->GetCharacter()->AccountName, i_nAddCredits);
		odbcStmt.ExecuteQuery((LPCSTR)szSQLQueryLog);
		odbcStmt.FreeStatement();
	}

	if(i_bSend2Client)
	{
		if(i_nAddCredits < 0) //payment
			this->SendString128(STRING_128_USER_NOTICE, "\\yYou've paid \\g%d\\y credits.\\y", i_nAddCredits * -1);
		else
			this->SendString128(STRING_128_USER_NOTICE, "\\yYou acquired \\g%d\\y credits.\\y", i_nAddCredits);


		int nTotalMoney = 0;
		int nMCash = 0;
		int nGiftCard = 0;
		Err_t nRetedErr = CashItemMoneyPay(&nTotalMoney, &nMCash, &nGiftCard);
		if (ERR_NO_ERROR != nRetedErr)
		{
			SendErrorMessage(T_FC_CHARACTER_GET_CASH_MONEY_COUNT, nRetedErr);
			return;
		}

		///////////////////////////////////////////////////////////////////////////////
		// Ĺ¬¶óŔĚľđĆ®żˇ ŔüĽŰÇŃ´Ů
		INIT_MSG_WITH_BUFFER(MSG_FC_CHARACTER_GET_CASH_MONEY_COUNT_OK, T_FC_CHARACTER_GET_CASH_MONEY_COUNT_OK, pSOK, SendBuf);
		pSOK->nMCash = nMCash;
		pSOK->nGiftCard = nGiftCard;
		SendAddData(SendBuf, MSG_SIZE(MSG_FC_CHARACTER_GET_CASH_MONEY_COUNT_OK));
	}
}

