///////////////////////////////////////////////////////////////////////////////
/// \fn			BOOL CFieldIOCPSocket::CompareSecondaryPassword(char *i_szSecPass)
/// \brief		
/// \author		cmkwon
/// \date		2007-09-13 ~ 2007-09-13
/// \warning	
///
/// \param		
/// \return		
///////////////////////////////////////////////////////////////////////////////
BOOL CFieldIOCPSocket::CompareSecondaryPassword(char *i_szSecPass)
{
	if(FALSE == IsSettingSecondaryPassword())
	{// 2007-09-13 by cmkwon, ĆĐ˝şżöµĺ°ˇ ĽłÁ¤µÇľî ŔÖÁö ľĘŔ¸¸é FALSE¸¦ ¸®ĹĎ
		return FALSE;
	}

	if(0 == strnicmp(m_szSecondaryPassword, i_szSecPass, SIZE_MAX_PASSWORD_MD5_STRING))
	{// 2007-09-13 by cmkwon, 2Â÷ĆĐ˝şżöµĺ°ˇ µżŔĎÇĎ´Ů
		return TRUE;
	}

	if(FALSE == CheckCommandExecutability(RACE_OPERATION|RACE_GAMEMASTER))
	{// 2007-09-13 by cmkwon, °ü¸®ŔÚ/żîżµŔÚ°ˇ ľĆ´Ď¸é FALSE¸¦ ¸®ĹĎ
		return FALSE;
	}

	///////////////////////////////////////////////////////////////////////////////
	// 2007-09-13 by cmkwon, °ü¸®ŔÚ/żîżµŔÚ´Â ÇŃ°ˇÁö ĂĽĹ©¸¦ ´ő ÇŃ´Ů.
	char szEncodedString[SIZE_MAX_PASSWORD_MD5_STRING];		MEMSET_ZERO(szEncodedString, SIZE_MAX_PASSWORD_MD5_STRING);
	BYTE byPass[SIZE_MAX_PASSWORD_MD5];
	MD5 md5_instance;

	md5_instance.MD5Encode(m_szSecondaryPassword, byPass);
	MD5::MD5Binary2String(byPass, szEncodedString);

	if(0 == strnicmp(szEncodedString, i_szSecPass, SIZE_MAX_PASSWORD_MD5_STRING))
	{// 2007-09-13 by cmkwon, 2Â÷ĆĐ˝şżöµĺ°ˇ µżŔĎÇĎ´Ů
		return TRUE;
	}

	return FALSE;
}

