void CFieldIOCPSocket::SendSplashAttackKillFeedMessages()
{
	for (const auto& msg : this->m_splashAttackDeadMessages)
	{
		INIT_MSG_WITH_BUFFER(MSG_FC_CHARACTER_DEAD_NOTIFY_MAP, T_FC_CHARACTER_DEAD_NOTIFY_MAP, msgSend, msgSendBuf);
		msgSend->AttackerInfluence = msg.AttackerInfluence;
		msgSend->TargetInfluence = msg.TargetInfluence;
		//msgSend->DamageItem = msg.DamageItem; //stattrack
		msgSend->DamageType = msg.DamageType;
		msgSend->MapChannel = msg.MapChannel;
		STRNCPY_MEMSET(msgSend->AttackerName, msg.AttackerName, SIZE_MAX_CHARACTER_NAME);
		STRNCPY_MEMSET(msgSend->TargetName, msg.TargetName, SIZE_MAX_CHARACTER_NAME);
		m_pCurrentFieldMapChannel->SendMessageToAllInChannel(msgSendBuf, MSG_SIZE(MSG_FC_CHARACTER_DEAD_NOTIFY_MAP), INFLUENCE_TYPE_ALL_MASK, 0);
	}
	this->m_splashAttackDeadMessages.clear();
}